'use strict';
const KEY='forma-tracker-v2', TODAY=localDate(new Date());
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dateObj(s){return new Date(s+'T12:00:00')}
function shift(s,n){let d=dateObj(s);d.setDate(d.getDate()+n);return localDate(d)}
function dayIndex(s){return (dateObj(s).getDay()+6)%7}
function fmtDate(s,long=false){return dateObj(s).toLocaleDateString('ru-RU',{day:'numeric',month:long?'long':'short',...(long?{weekday:'long'}:{})})}
function displayText(s){let text=String(s??'');const named={amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:' ',ndash:'–',mdash:'—',laquo:'«',raquo:'»',hellip:'…'};for(let pass=0;pass<3;pass++){const next=text.replace(/&(#x[0-9a-f]+|#[0-9]+|amp|lt|gt|quot|apos|nbsp|ndash|mdash|laquo|raquo|hellip);/gi,(whole,key)=>{if(key[0]!=='#')return named[key.toLowerCase()]??whole;let code=key[1].toLowerCase()==='x'?parseInt(key.slice(2),16):Number(key.slice(1));return code>0&&code<=0x10ffff&&!(code>=0xd800&&code<=0xdfff)?String.fromCodePoint(code):''});if(next===text)break;text=next}return text.replace(/<\/?(?:p|br|b|strong|i|em|span|div|small)(?:\s[^<>]*)?\s*\/?>/gi,' ').replace(/[\u00a0\u200b]/g,' ')}
function esc(s){return displayText(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const round=n=>Math.round(n),num=(n,d=0)=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:d}), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const ICONS={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',food:'<path d="M5 3v7m4-7v7M3 3v5a4 4 0 0 0 8 0V3M7 12v9M17 3c-3 4-3 8 2 8V3v18"/>',gym:'<path d="M6 5v14M3 8v8M18 5v14M21 8v8M6 12h12"/>',chart:'<path d="M4 3v17h17M7 15l4-5 4 3 5-8"/>',book:'<path d="M12 5v16M3 4c3-1 6 0 9 2 3-2 6-3 9-2v15c-3-1-6 0-9 2-3-2-6-3-9-2z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',drop:'<path d="M12 2c-3 5-7 9-7 13a7 7 0 0 0 14 0c0-4-4-8-7-13z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m12 8-3 5-4 1m7-6 4 5 4 1M9 13l4 2 2 6M12 8l-1 8-4 5"/>',scale:'<path d="M5 5h14l3 16H2z"/><path d="M8 8a5 5 0 0 1 8 0m-4 3 2-3"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4zM13 7l4 4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2m-3-7-2 2M7 17l-2 2M5 5l2 2m10 10 2 2"/>'};
function ico(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.food}</svg>`}
const defaults={version:1,profile:{age:'',height:'',baseline:'',kcal:2000,protein:160,fat:65,steps:7500,water:2250,dayA:2,dayB:5,club:'club1',clubNames:{club1:'Зал 1',club2:'Зал 2'},start:TODAY,notes:'',foodsNote:'Без мяты. Другие ограничения можно указать здесь.'},days:{},measurements:[],shopping:{},completed:{},notes:{}};
let state,storageOK=true;
function readStoredState(){for(const key of [KEY,KEY+'-recovery','forma-public-personal-v1',KEY+'-before-tracker-v2']){try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw&&raw.version===1&&raw.profile&&raw.days&&Array.isArray(raw.measurements))return raw}catch{}}return null}
try{const raw=readStoredState();state=raw?{...structuredClone(defaults),...raw,profile:{...defaults.profile,...raw.profile}}:structuredClone(defaults)}catch{state=structuredClone(defaults);storageOK=false}
let persistedState=structuredClone(state);
function mergeStoredChanges(base,current,latest){if(JSON.stringify(base)===JSON.stringify(current))return structuredClone(latest);if(current===null||typeof current!=='object')return structuredClone(current);if(Array.isArray(current)){const key=[...current,...(base||[]),...(latest||[])].every(x=>x&&typeof x==='object'&&(x.id||x.date))?'record':null;if(!key)return structuredClone(current);const id=x=>x.id||x.date,b=Object.fromEntries((base||[]).map(x=>[id(x),x])),c=Object.fromEntries(current.map(x=>[id(x),x])),l=Object.fromEntries((latest||[]).map(x=>[id(x),x]));return Object.values(mergeStoredChanges(b,c,l))}const result=latest&&typeof latest==='object'&&!Array.isArray(latest)?structuredClone(latest):{};for(const k of new Set([...Object.keys(base||{}),...Object.keys(current)])){if(['__proto__','constructor','prototype'].includes(k))continue;if(!(k in current)){delete result[k];continue}if(JSON.stringify(base?.[k])!==JSON.stringify(current[k]))result[k]=mergeStoredChanges(base?.[k],current[k],latest?.[k])}return result}
let DATA,view='home',selected=TODAY,workout='A',timerEnd=0,timerInterval=null;
try{timerEnd=Number(localStorage.getItem(KEY+'-timer'))||0}catch{}
const root=document.getElementById('app'),modal=document.getElementById('modal');
function save(){try{const latest=readStoredState();if(latest)state=mergeStoredChanges(persistedState,state,latest);state.savedAt=new Date().toISOString();const serialized=JSON.stringify(state);localStorage.setItem(KEY,serialized);if(localStorage.getItem(KEY)!==serialized)throw Error('Storage verification failed');persistedState=structuredClone(state);storageOK=true;writeRecoveryDatabase(state);try{localStorage.setItem(KEY+'-recovery',serialized)}catch{}document.querySelectorAll('.save-status').forEach(x=>x.textContent='Сохранено на этом устройстве');updateStorageWarning();return true}catch{storageOK=false;writeRecoveryDatabase(state);updateStorageWarning();toast('Не удалось сохранить. Экспортируй резервную копию.');return false}}

let toastTimeout;function toast(s){if(!storageOK&&!String(s).startsWith('Не удалось сохранить'))s='Сохранение в браузере не работает. Не закрывай страницу: скачай резервную копию.';const t=document.getElementById('toast');t.textContent=s;t.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('visible'),3500)}
function day(s=selected){return state.days[s]||={meals:{},water:0,steps:'',sets:{},custom:[],cardio:''}}
function targetCarbs(){return Math.max(0,round((state.profile.kcal-state.profile.protein*4-state.profile.fat*9)/4))}
function recipe(id){return DATA.recipes.find(r=>r.id===id)}
function mealFor(slot,s=selected){const logged=day(s).meals[slot];const r=recipe(logged?.id||DATA.menus[dayIndex(s)][slot]);return {...r,foods:r.foods.map(([f,g],i)=>[f,logged?.grams?.[i]??g])}}
function macros(foods){return [0,1,2,3].map(i=>foods.reduce((n,[f,g])=>n+(DATA.foods[f]?.[i]||0)*g/100,0))}
function sum(vs){return vs.reduce((a,v)=>a.map((n,i)=>n+(v[i]||0)),[0,0,0,0])}
function planned(s=selected){return sum([0,1,2,3].map(i=>macros(mealFor(i,s).foods)))}
function eaten(s=selected){const d=day(s);return sum([...Array.from({length:4},(_,i)=>d.meals[i]?.done?macros(mealFor(i,s).foods):[0,0,0,0]),...(d.custom||[]).map(c=>[c.kcal,c.p,c.f,c.c])])}
function trainingDay(s=selected){const d=dayIndex(s);return d===Number(state.profile.dayA)?'A':d===Number(state.profile.dayB)?'B':null}
function weekNumber(){return Math.max(1,Math.floor((dateObj(selected)-dateObj(state.profile.start))/86400000/7)+1)}
const NAV=[['home','Сегодня','home'],['meals','Питание','food'],['training','Зал','gym'],['progress','Прогресс','chart'],['guide','Гайд','book']];
function nav(){document.getElementById('sidebar').innerHTML=`<div class="brand">ФОРМА<span>/</span></div><p class="brand-sub">ТВОЯ ЛИЧНАЯ ПРОГРАММА</p><div class="side-links">${NAV.map(([v,t,i])=>`<button class="nav-btn ${view===v?'active':''}" data-nav="${v}">${ico(i)}${t}</button>`).join('')}</div><div class="side-bottom"><strong>${num(state.profile.kcal)} ккал в день</strong>${state.profile.baseline?esc(state.profile.age)+' лет · '+esc(state.profile.height)+' см · старт '+num(state.profile.baseline,1)+' кг':'Личные параметры — в профиле'}<br><button class="nav-btn" data-nav="settings">${ico('settings')}Мой профиль</button><small>Данные в этом браузере</small></div>`;document.getElementById('mobile-nav').innerHTML=NAV.map(([v,t,i])=>`<button class="nav-btn ${view===v?'active':''}" data-nav="${v}">${ico(i)}<span>${t}</span></button>`).join('');document.getElementById('header').innerHTML=`<div class="crumb">Моя программа / <b>${NAV.find(n=>n[0]===view)?.[1]||'Мой профиль'}</b></div><div class="header-right"><button class="save-status text-link" data-storage="check">${storageOK?'Проверить сохранение':'Ошибка сохранения'}</button><button class="icon-btn" data-nav="settings" aria-label="Открыть профиль">${ico('settings')}</button><div class="avatar">Я</div></div>`}
function dateControl(){return `<div class="date-control"><button class="icon-btn" data-action="date-prev" aria-label="Предыдущий день">${ico('left')}</button><input type="date" id="selected-date" aria-label="Дата программы" value="${selected}"><button class="icon-btn" data-action="date-next" aria-label="Следующий день">${ico('right')}</button></div>`}
function head(title,desc,dates=true){return `<div class="page-head"><div><div class="eyebrow">${esc(fmtDate(selected,true))}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div>${dates?dateControl():''}</div>`}
function weekStrip(){const first=shift(selected,-dayIndex(selected));return `<div class="week-strip">${Array.from({length:7},(_,i)=>{let d=shift(first,i);return `<button class="day-btn ${d===selected?'active':''}" data-date="${d}">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'][i]}<b>${dateObj(d).getDate()}</b>${trainingDay(d)?'<i title="День зала"></i>':''}</button>`}).join('')}</div>`}
function macroCards(){let vals=eaten(),t=[state.profile.kcal,state.profile.protein,state.profile.fat,targetCarbs()];return `<div class="grid four">${['Калории','Белок','Жиры','Углеводы'].map((label,i)=>`<div class="card"><div class="stat-top">${i===0?ico('food'):''}${label}</div><div class="stat-num">${num(round(vals[i]))} <span>/ ${num(t[i])} ${i===0?'ккал':'г'}</span></div><div class="track"><i style="width:${clamp(vals[i]/Math.max(t[i],1)*100,0,100)}%"></i></div><small>${vals[i]>t[i]?'Выше ориентира на '+num(round(vals[i]-t[i])):'Осталось '+num(round(t[i]-vals[i]))} ${i===0?'ккал':'г'}</small></div>`).join('')}</div>`}
function miniMeal(i){let r=mealFor(i),m=macros(r.foods),done=!!day().meals[i]?.done;return `<div class="meal-line ${done?'meal-done':''}"><div class="meal-icon">${ico(i===0?'sun':'food')}</div><div class="meal-copy"><small>${r.type}</small><h3>${esc(r.name)}</h3><small>${round(m[0])} ккал <span>· Б ${round(m[1])} г</span></small></div><button class="check-btn ${done?'checked':''}" data-action="toggle-meal" data-slot="${i}" aria-label="${done?'Снять отметку':'Съедено'}: ${esc(r.type)}" aria-pressed="${done}">${done?ico('check'):ico('plus')}</button></div>`}
function home(){const d=day(),tr=trainingDay(),mealCount=[0,1,2,3].filter(i=>d.meals[i]?.done).length;return head('Твой план на сегодня','Питание и движение в ритме обычной жизни.')+`${!state.profile.baseline?'<div class="info-strip">Заполни параметры в профиле. Они сохранятся только на твоём устройстве. <button class="text-link" data-nav="settings">Мой профиль</button></div>':''}<section class="hero"><div class="hero-copy"><div class="eyebrow">ПЕРСОНАЛЬНЫЙ ПЛАН · НЕДЕЛЯ ${weekNumber()}</div><h2>Снижаем жир.<br>Сохраняем силу.</h2><p>Среда и выходной — фуллбоди с акцентом на верх тела. В остальные дни — привычная ходьба и восстановление.</p><div class="hero-metrics"><div><b>${num(state.profile.kcal)}</b><small>ккал на старте</small></div><div><b>${state.profile.protein} г</b><small>белка в день</small></div><div><b>2</b><small>силовые в неделю</small></div></div><button class="btn lime small" data-nav="${tr?'training':'meals'}">${tr?'Открыть тренировку '+tr:'Моё меню на день'}${ico('arrow')}</button></div><div class="hero-photo" role="img" aria-label="Тарелка с разнообразной едой"></div></section><div class="section-head"><h2>Питание за день</h2><span class="tag">${mealCount} из 4 приёмов</span></div>${macroCards()}<div class="grid layout-main" style="margin-top:22px"><section class="card"><div class="flex between"><h3>Твоё меню</h3><button class="text-link" data-nav="meals">Порции и замены ${ico('right')}</button></div>${[0,1,2,3].map(miniMeal).join('')}${d.custom?.length?`<div class="tip">Дополнительно: ${d.custom.map(c=>esc(c.name)).join(', ')}. Эти калории уже учтены.</div>`:''}</section><div class="grid"><section class="card"><div class="flex between"><h3>${tr?'Сегодня зал':'День восстановления'}</h3>${ico(tr?'gym':'walk')}</div><div class="training-banner"><div class="mini-label">${tr?'ФУЛЛБОДИ '+tr:'ПРИВЫЧНЫЙ ТЕМП'}</div><strong>${tr?'Верх тела + умеренно ноги':'Ходьба и обычная активность'}</strong><p class="muted" style="font-size:12px;margin:7px 0 12px">${tr?'Около 60–80 минут с разминкой и кардио. Первые недели не тренируемся до отказа.':'Ориентир шагов — удобная цель, а не обязанность идти через усталость.'}</p><button class="btn small soft" data-nav="${tr?'training':'progress'}">${tr?'Перейти к упражнениям':'Записать замеры'}${ico('arrow')}</button></div><div class="inline-input" style="margin-top:16px"><label style="flex:1">Шаги за день<input type="number" id="daily-steps" min="0" max="100000" inputmode="numeric" placeholder="Например, 7500" value="${esc(d.steps)}"></label><button class="icon-btn" data-action="save-steps" aria-label="Сохранить шаги">${ico('check')}</button></div></section><section class="card"><div class="flex between"><h3>Вода и напитки</h3>${ico('drop')}</div><div class="mini-num">${num(d.water/1000,2)} <span class="muted" style="font-size:14px">/ ${num(state.profile.water/1000,2)} л</span></div><div class="water-cups">${Array.from({length:8},(_,i)=>`<i class="${d.water>=state.profile.water*(i+1)/8?'full':''}"></i>`).join('')}</div><div class="flex"><button class="btn small soft" data-action="water" data-add="250">+250 мл</button><button class="btn small outline" data-action="water" data-add="-250">−250</button></div><p class="tip">Пей по жажде. Чай и кофе тоже считаются. Медицинские ограничения жидкости важнее ориентира.</p></section></div></div><p class="long-note" style="margin-top:22px">Показатели питания рассчитываются по отмеченным блюдам и твоим порциям. Пока блюдо не отмечено, оно входит только в план, а не в съеденное.</p>`}
function mealCard(i){let r=mealFor(i),m=macros(r.foods),done=!!day().meals[i]?.done;return `<article class="card meal-card"><div class="meal-card-head"><div><div class="eyebrow">${r.type}</div><h3>${esc(r.name)}</h3><div class="macro-mini" style="margin-top:8px">≈${round(m[0])} ккал · Б ${round(m[1])} · Ж ${round(m[2])} · У ${round(m[3])} г</div></div><button class="check-btn ${done?'checked':''}" data-action="toggle-meal" data-slot="${i}" aria-label="Отметить ${r.type}" aria-pressed="${done}">${done?ico('check'):ico('plus')}</button></div><div class="ingredients">${r.foods.map(([f,g],j)=>`<div class="ingredient"><span class="food-name">${esc(f)}</span><input type="number" aria-label="Граммы: ${esc(f)}" min="0" max="2000" step="1" inputmode="numeric" data-portion="${i}" data-food="${j}" value="${g}"><span class="muted">г</span></div>`).join('')}</div><div class="method">${esc(r.method)}</div><div class="meal-footer"><button class="btn small outline" data-action="swap" data-slot="${i}">${ico('edit')}Заменить блюдо</button><span class="completion">${done?'Учтено в дневнике':'План на день'}</span></div></article>`}
function meals(){let t=planned(),d=day();return head('Твоё питание','Семь вариантов дня около 2000 ккал. Блюда и порции можно менять.')+weekStrip()+`<div class="nutrition-total"><div><small>План выбранного дня</small><br><strong>${round(t[0])} <span>ккал</span></strong></div><span><b>Б ${round(t[1])}</b> / Ж ${round(t[2])} / У ${round(t[3])} г</span><button class="btn small soft" data-action="shopping">${ico('food')}Список покупок</button></div><div class="info-strip">Граммовки мяса и рыбы — сырые, круп — сухие, фасоли — готовые. Калории примерные: сверяй этикетки. В меню нет мяты. Проверь состав покупных продуктов и сохрани другие ограничения в профиле.</div><div class="grid two">${[0,1,2,3].map(mealCard).join('')}</div><div class="section-head"><h2>Дополнительно съедено</h2><button class="btn small soft" data-action="custom-meal">${ico('plus')}Добавить</button></div>${(d.custom||[]).length?d.custom.map((c,i)=>`<div class="card flex between" style="margin-bottom:10px"><div><strong>${esc(c.name)}</strong><div class="macro-mini">${c.kcal} ккал · Б ${c.p} / Ж ${c.f} / У ${c.c} г</div></div><button class="icon-btn" data-action="remove-custom" data-index="${i}" aria-label="Удалить запись">${ico('close')}</button></div>`).join(''):`<div class="empty">Здесь можно учесть десерт, напиток, соус или другую еду вне меню.</div>`}<p class="long-note" style="margin-top:17px">На дни зала не нужно автоматически добавлять калории с тренажёра или часов. Банан и йогурт из меню можно перенести ближе к занятию. Рецепты рассчитаны на одну порцию.</p>`}
const EXERCISES={
legpress:{name:'Жим ногами в тренажёре',muscle:'Квадрицепсы и ягодицы',reps:'10–15',sets:2,rest:120,alternatives:['Жим ногами горизонтальный','Жим ногами под углом'],tech:'Настрой сиденье так, чтобы таз и спина сохраняли опору. Стопы всей поверхностью на платформе. Сгибай ноги в комфортной амплитуде без отрыва таза. Не запирай колени и не задерживай дыхание. Не ищи максимальную глубину любой ценой.'},
chest:{name:'Жим от груди в тренажёре',muscle:'Грудь, трицепс',reps:'10–12',sets:3,rest:120,alternatives:['Горизонтальный жим сидя','Жим в рычажном тренажёре'],tech:'Рукояти примерно на уровне середины груди. Спина на опоре, шея в комфортном нейтральном положении. Плавно выжимай, без рывка и болезненного растяжения плеч. Локти не разводи предельно в стороны.'},
row:{name:'Горизонтальная тяга с опорой',muscle:'Средняя часть спины',reps:'10–12',sets:3,rest:120,alternatives:['Тяга с упором грудью','Горизонтальная блочная тяга'],tech:'Предпочти опору грудью, если она доступна и удобна. Тяни локти назад без запрокидывания головы и раскачки корпуса. Своди лопатки умеренно, не пожимай плечами. Рукоять и хват должны быть комфортны для рук.'},
legcurl:{name:'Сгибание ног сидя',muscle:'Задняя поверхность бедра',reps:'12–15',sets:2,rest:90,alternatives:['Сгибание ног сидя','Сгибание ног лёжа'],tech:'Совмести ось коленного сустава с осью тренажёра, валик расположи по инструкции тренажёра. Сгибай плавно, удерживай таз на сиденье. Остановись при боли в колене или спине.'},
lateral:{name:'Отведение рук в тренажёре',muscle:'Средняя часть плеч',reps:'12–15',sets:2,rest:90,alternatives:['Отведение рук сидя в тренажёре','Отведение руки в нижнем блоке'],tech:'Начни с минимального комфортного веса. Поднимай руки без пожимания плечами и напряжения шеи. Не поднимай выше комфортного уровня плеч. Если тренажёр неудобен или появляются симптомы, пропусти упражнение.'},
biceps:{name:'Сгибание рук в тренажёре',muscle:'Бицепс',reps:'10–15',sets:2,rest:90,alternatives:['Сгибание рук в тренажёре','Сгибание рук в нижнем блоке'],tech:'Настрой опору, не выпрямляй локоть насильно. Сохраняй запястье в удобном положении и одинаково контролируй обе стороны. Не повышай вес при боли или заметном ограничении рук.'},
triceps:{name:'Разгибание рук на блоке',muscle:'Трицепс',reps:'10–15',sets:2,rest:90,alternatives:['Разгибание рук с канатом','Разгибание рук с прямой рукоятью'],tech:'Локти рядом с корпусом. Разгибай руки без раскачки и сильного наклона головы. Выбери канат или рукоять, при которой нет боли в кисти и локте.'},
pulldown:{name:'Тяга верхнего блока к груди',muscle:'Широчайшие, бицепс',reps:'10–12',sets:3,rest:120,alternatives:['Тяга верхнего блока нейтральным хватом','Вертикальная тяга в рычажном тренажёре'],tech:'Зафиксируй бёдра. Тяни рукоять перед собой к верхней части груди без рывка и запрокидывания головы. Не тяни за голову. Выбирай комфортную ширину хвата, не стремись насильно коснуться груди.'},
pec:{name:'Сведение рук в тренажёре',muscle:'Грудные мышцы',reps:'12–15',sets:2,rest:90,alternatives:['Сведение рук «бабочка»','Лёгкий жим от груди вместо сведения'],tech:'Рукояти или опоры настрой под комфортную амплитуду. Не уводи плечи далеко назад. Своди руки плавно, без сильного напряжения шеи. Можно пропустить при дискомфорте в плече.'}
};
const ROUTINES={A:['legpress','chest','row','legcurl','lateral','biceps','triceps'],B:['legpress','pulldown','chest','legcurl','row','lateral','triceps']};
const CLUBS={club1:'Зал 1',club2:'Зал 2'};
function club(){return day().club||state.profile.club||'club1'}
function setKey(id){return workout+'-'+club()+'-'+id}
function completedKey(){return selected+'-'+workout+'-'+club()}
function setCount(id){return weekNumber()<=2?2:EXERCISES[id].sets}
function setData(id,i){const key=setKey(id);const d=day();d.sets[key]||=[];return d.sets[key][i]||={kg:'',reps:'',rir:'',done:false}}
function previousSet(id,i){let dates=Object.keys(state.days).filter(s=>s<selected).sort().reverse();for(let dt of dates){let r=state.days[dt].sets?.[setKey(id)]?.[i];if(r?.done){const oldVariant=state.days[dt].variants?.[setKey(id)]||EXERCISES[id].alternatives[0],currentVariant=day().variants?.[setKey(id)]||EXERCISES[id].alternatives[0];if(oldVariant===currentVariant)return r}}return null}
function setRow(id,i){const s=setData(id,i),prev=previousSet(id,i);return `<div class="set-row ${s.done?'done':''}"><b>${i+1}</b><input type="number" min="0" max="1000" step="0.5" inputmode="decimal" aria-label="${esc(EXERCISES[id].name)}: вес, подход ${i+1}" placeholder="${prev?esc(prev.kg):'кг'}" value="${esc(s.kg)}" data-set="${id}" data-i="${i}" data-field="kg"><input type="number" min="1" max="100" step="1" inputmode="numeric" aria-label="Повторения, подход ${i+1}" placeholder="${prev?esc(prev.reps):'повт.'}" value="${esc(s.reps)}" data-set="${id}" data-i="${i}" data-field="reps"><input type="number" min="0" max="10" step="1" inputmode="numeric" aria-label="Запас повторений, подход ${i+1}" placeholder="3" value="${esc(s.rir)}" data-set="${id}" data-i="${i}" data-field="rir"><button class="check-btn ${s.done?'checked':''}" data-action="set-done" data-ex="${id}" data-index="${i}" aria-label="Завершить подход ${i+1}" aria-pressed="${s.done}">${ico('check')}</button></div>`}
function exerciseCard(id,i){const e=EXERCISES[id];let variant=day().variants?.[setKey(id)]||e.alternatives[0];return `<details class="card exercise" ${i===0?'open':''} data-ex-detail="${id}"><summary><div class="ex-num">${String(i+1).padStart(2,'0')}</div><div class="ex-title"><h3>${esc(e.name)}</h3><p>${e.muscle} · ${setCount(id)} × ${e.reps} · отдых ${e.rest/60} мин</p></div><span class="tag">${day().sets[setKey(id)]?.filter(s=>s.done).length||0}/${setCount(id)}</span></summary><div class="details-body"><div class="technique">${e.tech}</div><label>Вариант тренажёра<select data-variant="${id}">${e.alternatives.map(a=>`<option ${variant===a?'selected':''}>${esc(a)}</option>`).join('')}</select></label><div class="set-row labels"><span>Подход</span><span>Вес, кг</span><span>Повторения</span><span>Запас (RIR)</span><span></span></div><div class="sets">${Array.from({length:setCount(id)},(_,i)=>setRow(id,i)).join('')}</div><p class="field-note">Серым показан прошлый завершённый подход в этом зале и варианте упражнения. Это подсказка, а не запись за сегодня. Если модель тренажёра другая, подбери вес заново.</p></div></details>`}
function training(){return head('Твой зал','Два зала, отдельные записи. Фуллбоди с акцентом на верх тела.')+`<div class="info-strip">Стартовая программа предполагает отсутствие противопоказаний к нагрузке. Если есть травмы или заболевания, уточни ограничения у врача, настройку тренажёров — с тренером. При боли, головокружении или необычной головной боли остановись.</div><label style="margin-top:18px;max-width:420px">Твой зал<select id="training-club">${Object.entries(CLUBS).map(([k,v])=>`<option value="${k}" ${club()===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><p class="field-note">Рабочие веса и прошлые подходы хранятся отдельно для каждого зала. На новой модели начни с подбора нагрузки заново.</p><div class="flex between wrap"><div class="workout-tabs"><button class="${workout==='A'?'active':''}" data-workout="A">A · ${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][state.profile.dayA]}</button><button class="${workout==='B'?'active':''}" data-workout="B">B · ${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][state.profile.dayB]}</button></div><span class="tag">Неделя ${weekNumber()} · ${weekNumber()<=2?'по 2 подхода, запас 3–4':'запас 2–3 повторения'}</span></div><div class="grid layout-main"><div><div class="timer"><div><div class="timer-value" id="timer-value">00:00</div><p>Таймер отдыха</p></div><div class="timer-actions"><button class="btn small lime" data-action="timer" data-seconds="90">90 сек</button><button class="btn small outline" style="color:white;border-color:#536355" data-action="timer" data-seconds="120">120</button><button class="icon-btn" style="color:white" data-action="timer-stop" aria-label="Остановить таймер">${ico('close')}</button></div></div>${ROUTINES[workout].map(exerciseCard).join('')}<div class="card"><h3>Кардио после силовой</h3><p class="muted" style="font-size:12px;margin:9px 0 15px">10–20 минут ходьбы на дорожке или велотренажёра в разговорном темпе. Начни с 10 минут, если устаёшь. Без необходимости держаться за поручни с усилием или напрягать шею.</p><label>Фактически, минут<input id="cardio-minutes" type="number" min="0" max="180" inputmode="numeric" value="${esc(day().cardio)}" placeholder="Например, 15"></label><button class="btn" data-action="finish-workout" style="width:100%;margin-top:12px">${ico('check')}Сохранить тренировку ${workout}</button>${state.completed[completedKey()]?`<p class="feedback">Тренировка сохранена в истории. Изменения подходов сохраняются отдельно.</p>`:''}</div></div><aside><section class="card"><div class="eyebrow">ПЕРЕД ПЕРВЫМ ПОДХОДОМ</div><h3>Разминка и настройка</h3><p class="long-note" style="margin-top:13px">5–8 минут спокойного кардио. Затем 1–2 лёгких разминочных подхода перед первым жимом и тягой. Они не входят в рабочие подходы. Попроси тренера настроить сиденья и опоры.</p><div class="tip">Не нужно занимать все 1 ч 40 мин–2 часа тяжёлой работой. Около 60–80 минут с паузами часто достаточно. Дольше — только если спокойно и удобно.</div></section><section class="card" style="margin-top:17px"><h3>Как выбрать вес</h3><p class="long-note" style="margin-top:12px">Начни с лёгкого веса. Последние повторения должны требовать усилия, но оставлять ${weekNumber()<=2?'3–4':'2–3'} повтора с хорошей техникой в запасе. RIR — сколько таких повторов ты ещё смог бы сделать.</p><p class="tip">Когда все подходы два занятия подряд достигают верхней границы повторений без симптомов и с нужным запасом, попробуй минимальный шаг тренажёра. Если шаг слишком велик, сохрани вес.</p></section><section class="card" style="margin-top:17px"><h3>Третий день?</h3><p class="long-note" style="margin-top:12px">Первые 4 недели придерживайся двух силовых. Если хочется двигаться чаще, добавь прогулку или 20–30 минут лёгкого кардио по переносимости. Третья тяжёлая тренировка требует оценки восстановления.</p></section></aside></div>`}
function weightStats(){const ms=state.measurements.filter(m=>Number.isFinite(m.weight)&&m.weight>0&&m.date<=selected).sort((a,b)=>a.date.localeCompare(b.date));const a=ms.filter(m=>m.date>=shift(selected,-6)),b=ms.filter(m=>m.date>=shift(selected,-13)&&m.date<=shift(selected,-7));const avg=x=>x.reduce((n,m)=>n+m.weight,0)/x.length;return{ms,latest:ms.at(-1),avg:a.length?avg(a):null,delta:a.length>=3&&b.length>=3?avg(a)-avg(b):null,a:a.length,b:b.length}}
function chart(ms){if(!ms.length)return `<div class="empty" style="margin-top:18px">${ico('chart')}<h3>Здесь появится твоя динамика</h3>Запиши первый утренний вес. График покажет только сохранённые тобой замеры.</div>`;let min=Math.min(...ms.map(m=>m.weight))-.5,max=Math.max(...ms.map(m=>m.weight))+.5;let first=dateObj(ms[0].date).getTime(),last=dateObj(ms.at(-1).date).getTime(),range=Math.max(last-first,86400000);const x=m=>45+(dateObj(m.date).getTime()-first)/range*690,y=m=>175-(m.weight-min)/(max-min)*145;return `<svg class="chart" viewBox="0 0 780 220" role="img" aria-label="График веса по сохранённым замерам">${[0,1,2,3].map(i=>{let v=min+(max-min)*i/3,yy=175-i*145/3;return `<line x1="45" y1="${yy}" x2="750" y2="${yy}" stroke="#e2e8dd"/><text x="0" y="${yy+4}">${num(v,1)}</text>`}).join('')}<polyline points="${ms.map(m=>`${x(m)},${y(m)}`).join(' ')}" fill="none" stroke="#2b6349" stroke-width="2.5"/>${ms.map(m=>`<circle cx="${x(m)}" cy="${y(m)}" r="4" fill="#2b6349"><title>${esc(fmtDate(m.date))}: ${m.weight} кг</title></circle>`).join('')}<text x="45" y="208">${esc(fmtDate(ms[0].date))}</text><text x="685" y="208">${esc(fmtDate(ms.at(-1).date))}</text></svg>`}
function progress(){let s=weightStats(),current=state.measurements.find(m=>m.date===selected),advice=s.delta===null?'Для сравнения недель нужны минимум 3 замера в каждой из двух последних недель. Сейчас данных недостаточно.':s.delta<-.9?'Снижение заметное. В первые недели часть изменения — вода. Если такой темп держится или падают силы, рассмотри +100–200 ккал.':s.delta<-.2?'Вес постепенно снижается. Если сон, голод и силовые в порядке, сохраняй текущие ориентиры.':'Не меняй калории из-за одной недели. Посмотри на талию и учёт еды за 2–3 недели, прежде чем корректировать план.';return head('Твой прогресс','Средняя масса и талия говорят больше, чем одно утреннее взвешивание.')+`<div class="grid three"><div class="card"><div class="stat-top">Последний замер до выбранной даты</div><div class="stat-num">${s.latest?num(s.latest.weight,1):'—'} <span>кг</span></div><small>${s.latest?fmtDate(s.latest.date):'Запиши первый утренний замер'}</small></div><div class="card"><div class="stat-top">Среднее за последние 7 дней</div><div class="stat-num">${s.avg?num(s.avg,2):'—'} <span>кг</span></div><small>Замеров: ${s.a} из 7</small></div><div class="card"><div class="stat-top">Изменение среднего за неделю</div><div class="stat-num">${s.delta!==null?(s.delta>0?'+':'')+num(s.delta,2):'—'} <span>кг</span></div><small>${s.delta===null?'Нужно больше наблюдений':'Сравнение двух последних недель'}</small></div></div><div class="card" style="margin-top:18px"><div class="flex between"><h3>Динамика массы</h3><span class="tag">Только твои записи</span></div>${chart(s.ms)}<div class="feedback">${advice}</div></div><section class="card" style="margin-top:18px"><h3>Новый замер · ${esc(fmtDate(selected))}</h3><form id="measure-form"><div class="measure-row"><label>Вес утром, кг<input type="number" name="weight" min="35" max="250" step="0.1" inputmode="decimal" required placeholder="Например, 89.2" value="${current?.weight??''}"></label><label>Талия, см · необязательно<input type="number" name="waist" min="40" max="200" step="0.5" inputmode="decimal" placeholder="На спокойном выдохе" value="${current?.waist??''}"></label><label>Сон, часов · необязательно<input type="number" name="sleep" min="0" max="24" step="0.5" inputmode="decimal" placeholder="Например, 7.5" value="${current?.sleep??''}"></label><button class="btn" type="submit">Сохранить</button></div><label style="margin-top:12px">Самочувствие / заметка<textarea name="note" rows="2" maxlength="600" placeholder="Голод, усталость, силовые, особенности дня">${esc(current?.note||'')}</textarea></label></form><p class="field-note">Масса — после туалета, до еды. Талия — раз в неделю в одном месте. Повторное сохранение заменит запись выбранной даты.</p></section><div class="grid two" style="margin-top:18px"><section class="card"><h3>История замеров</h3>${state.measurements.length?`<table class="measure-table"><thead><tr><th>Дата</th><th>кг</th><th>Талия</th><th></th></tr></thead><tbody>${[...state.measurements].sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<tr><td><button class="text-link" data-date="${m.date}">${esc(fmtDate(m.date))}</button></td><td>${m.weight}</td><td>${m.waist??'—'}</td><td><button class="icon-btn" data-action="delete-measure" data-date-id="${m.date}" aria-label="Удалить замер ${m.date}">${ico('close')}</button></td></tr>`).join('')}</tbody></table>`:'<p class="long-note" style="margin-top:15px">Записей пока нет. График начнётся с первого сохранённого замера.</p>'}</section><section class="card"><h3>История зала</h3>${Object.values(state.completed).length?Object.values(state.completed).sort((a,b)=>b.date.localeCompare(a.date)).map(c=>`<div class="history-item"><strong>${esc(fmtDate(c.date))} · Фуллбоди ${esc(c.workout)}</strong><br><span class="muted">${c.sets} рабочих подходов · ${esc(CLUBS[c.club]||'Зал')}${c.cardio?` · кардио ${c.cardio} мин`:''}</span></div>`).join(''):'<p class="long-note" style="margin-top:15px">После занятия нажми «Сохранить тренировку». Здесь появятся фактически выполненные подходы.</p>'}</section></div>`}
const CHAPTERS=[
['Твои стартовые ориентиры','Личные параметры задаются в профиле и сохраняются только в браузере. Базовая схема: 2000 ккал, белок 160 г, жиры 65 г, углеводы около 194 г. Это стартовый ориентир для настройки по динамике, а не измеренный обмен веществ.'],
['Почему 2000 ккал и когда пересматривать','Энергетические потребности зависят от массы, роста, возраста и активности. 2000 ккал — пробная точка, которая может оказаться дефицитом или поддержанием. Оценивай её по динамике за 2–3 недели. Если устойчиво падают рабочие веса, сон и самочувствие, подумай о прибавке 100–200 ккал, а не о дополнительном кардио.'],
['Темп снижения и недельное среднее','После первых 1–2 недель рабочий диапазон примерно 0,3–0,7 кг в неделю. Первые изменения могут отражать воду. Взвешивайся 4–7 раз в неделю, сравнивай средние и талию. Если 2–3 недели масса и талия стоят, сначала проверь масло, напитки, выходные и порции. Меняй только один фактор за раз.'],
['Белок и растительные источники','160 г — около 1,8 г/кг твоей исходной массы. Раздели на 3–4 приёма, без необходимости точного расписания. Считай и растительный белок: не дели его автоматически пополам. Чередуй бобовые, сою, крупы. Протеин удобен, когда обычной еды не хватает, но не обязателен.'],
['Жиры и углеводы','65 г жиров — около 29% энергии стартового рациона. Подойдут масла, орехи, яйца, молочные продукты, рыба. Насыщенные жиры разумно ограничить примерно 22 г на 2000 ккал. Углеводы помогают работе в зале: крупы, картофель, хлеб, фрукты и бобовые. Гликемический индекс отдельного продукта не заменяет учёт порций и качества всего питания.'],
['Клетчатка, вода и сытость','Ориентир клетчатки 25–35 г/день с постепенным увеличением. Ешь разнообразные овощи, фрукты, цельные крупы и бобовые. ВОЗ рекомендует минимум 400 г овощей и фруктов и 25 г клетчатки для взрослых. 2–2,5 л напитков — только удобный старт с поправкой на жажду, жару и медицинские ограничения.'],
['Сырой и готовый вес','Вес должен совпадать с записью в базе. В этом меню мясо и рыба сырые, крупы сухие, фасоль готовая. Вода меняет массу блюда, но не добавляет калорий. Для общего рецепта: посчитай калории всех ингредиентов, взвесь итог блюда и раздели калории на его готовую массу. Масло, соусы, напитки и перекусы тоже учитываются.'],
['Магазин, масло и готовка','Надписи «фитнес» и «без сахара» не гарантируют низкую калорийность. Сравни белок, жиры и порцию. Для готовки удобны духовка, аэрогриль, тушение и мультиварка. Масло 5 г ≈45 ккал, 10 г ≈90 ккал. Спрей экономит калории, только если ты используешь меньше масла. Быстро охлаждай готовую еду, храни порции в холодильнике, излишки замораживай.'],
['Питание в день фуллбоди','За 1–3 часа — привычная еда с белком и углеводами. Если времени мало — небольшой переносимый перекус. После зала подойдёт обычный обед или ужин в ближайшие часы. Срочно пить сахар не нужно. Переноси приёмы пищи, сохраняя суточный план. «Сожжённые» калории часов не добавляем автоматически.'],
['Твои залы и оборудование','Назови два зала в профиле. Программа хранит рабочие веса отдельно для каждого. Варианты упражнений — типы тренажёров для подбора в зале. Не переноси килограммы механически между разными моделями. Попроси тренера показать подходящие аналоги и настройки.'],
['Прогрессия в тренажёрах','Первые 2 недели по 2 рабочих подхода, запас 3–4 повтора. Затем по плану, обычно с запасом 2–3. Когда два занятия подряд достигаешь верхней границы повторений с техникой и без симптомов, можно попробовать минимальную прибавку. На дефиците сохранение силы уже хороший результат. Вес на разных моделях тренажёров напрямую не сравнивай.'],
['Здоровье и безопасная нагрузка','Уточни индивидуальные ограничения при заболеваниях и после травм у врача, а настройку тренажёров — с тренером. Не задерживай дыхание, не делай рывков и не работай через боль или головокружение. При внезапных выраженных неврологических симптомах нужна срочная медицинская помощь. Личные медицинские заметки можно записать в профиле: они останутся на твоём устройстве.'],
['Витамины и спортивные добавки','Сначала полноценная еда. Железо и высокие дозы витамина D без показаний не назначаем. Анализы подбирают по симптомам и рискам, а не всем подряд. Креатин моногидрат 3–5 г/день может помогать силовой работе, но не обязателен и способен увеличить массу из-за воды в мышцах. При болезнях почек и лекарственной терапии добавки обсуждают с врачом. BCAA при достаточном белке обычно не нужны.'],
['Кофеин, соль и алкоголь','Для здоровых взрослых EFSA указывает до 200 мг кофеина разово и до 400 мг за день как обычно не вызывающие опасений количества. Это не обязательная доза. Оцени сон и переносимость. Ориентир ВОЗ по соли — менее 5 г за сутки из всех продуктов. У алкоголя нет безрискового уровня для здоровья, он добавляет калории и может мешать сну и аппетиту. Не голодай ради алкоголя и не компенсируй застолье наказанием в зале.'],
['Любимая еда и поддержание','Примерно 80–90% рациона удобно строить на продуктах, дающих белок, клетчатку и нутриенты. Остальное можно оставить любимой еде, учитывая калории. Если дефицит становится трудно переносить, 1–2 недели на текущем поддержании могут помочь с соблюдением. Это не обязательный «разгон метаболизма». Вес на перерыве способен вырасти из-за воды и гликогена.'],
['Что будет после этапа снижения','Не нужно заранее назначать идеальную конечную массу по одному росту. После снижения примерно на 4–5 кг оцени талию, силы, внешний вид и самочувствие. Для будущего набора сначала найди поддержание на новом весе, затем при необходимости небольшой профицит. Рост общей массы и прирост чистых мышц — разные показатели.'],
['Хранение данных на телефоне','Записи хранятся только в браузере на этом устройстве. Другой браузер, приватный режим или удаление данных сайта могут лишить тебя истории. Регулярно экспортируй резервную копию в профиле. На другом устройстве её можно импортировать. Автоматической облачной синхронизации нет. Чтобы быстро открывать сайт, используй «На экран Домой» в меню браузера.']
];
function guide(){return head('Твоя инструкция','Короткие ответы по питанию, тренировкам и восстановлению.',false)+`<div class="guide">${CHAPTERS.map(([title,body],i)=>`<details><summary><span>${String(i+1).padStart(2,'0')} / ${title}</span></summary><p>${body}</p></details>`).join('')}</div><section class="card source-list" style="margin-top:25px"><h3>Источники рекомендаций</h3>${DATA.sources.map(([n,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(n)} ↗</a>`).join('')}<p class="long-note">Меню основано на типовых значениях пищевой ценности. Структура тренировки — общий вариант для умеренной силовой нагрузки с учётом заявленного графика, а не медицинское назначение. Фото: Unsplash, иллюстрация питания.</p></section>`}
function settings(){const p=state.profile;return head('Твой профиль','Исходные параметры, удобный график и резервная копия.',false)+`<form id="profile-form"><div class="grid two"><div><section class="card setting-card"><h3>Параметры и питание</h3><div class="setting-grid"><label>Возраст, лет<input name="age" type="number" min="18" max="90" required value="${p.age}"></label><label>Рост, см<input name="height" type="number" min="130" max="230" required value="${p.height}"></label><label>Исходная масса, кг<input name="baseline" type="number" min="35" max="250" step=".1" required value="${p.baseline}"></label><label>Дата начала программы<input name="start" type="date" required value="${esc(p.start)}"></label><label>Калории в день<input name="kcal" type="number" min="1600" max="4000" step="50" required value="${p.kcal}"></label><label>Белок, г<input name="protein" type="number" min="80" max="240" step="5" required value="${p.protein}"></label><label>Жиры, г<input name="fat" type="number" min="45" max="140" step="5" required value="${p.fat}"></label><label>Ориентир шагов<input name="steps" type="number" min="0" max="25000" step="500" required value="${p.steps}"></label><label>Ориентир воды, мл<input name="water" type="number" min="500" max="4000" step="250" required value="${p.water}"></label></div><p class="field-note">Изменение калорий меняет ориентиры дневника, а не порции меню. Порции редактируются в питании. Историю массы записывай в «Прогрессе». Калории не меняются автоматически.</p></section><section class="card setting-card"><h3>Твои дни зала</h3><div class="setting-grid"><label>Название первого зала<input name="club1Name" maxlength="80" value="${esc(state.profile.clubNames?.club1||'Зал 1')}"></label><label>Название второго зала<input name="club2Name" maxlength="80" value="${esc(state.profile.clubNames?.club2||'Зал 2')}"></label></div><div class="setting-grid" style="margin-top:15px">${['A','B'].map((a,i)=>`<label>Фуллбоди ${a}<select name="day${a}">${['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'].map((d,j)=>`<option value="${j}" ${Number(p['day'+a])===j?'selected':''}>${d}</option>`).join('')}</select></label>`).join('')}</div><p class="field-note">По умолчанию среда и суббота. Между силовыми желательно оставлять хотя бы день восстановления. Субботу можно заменить воскресеньем.</p></section></div><div><section class="card setting-card"><h3>Питание и здоровье</h3><label>Аллергии, непереносимости, нелюбимые продукты<textarea name="foodsNote" rows="3" maxlength="1000">${esc(p.foodsNote)}</textarea></label><label style="margin-top:14px">Самочувствие и ограничения<textarea name="notes" rows="5" maxlength="2000">${esc(p.notes)}</textarea></label><p class="field-note">Это твои заметки. Сайт не анализирует их автоматически и не исключает продукты из меню. Используй замену блюда и проверяй состав.</p></section><button class="btn" type="submit" style="width:100%">${ico('check')}Сохранить профиль</button><section class="card setting-card" style="margin-top:18px"><h3>Твоя история под контролем</h3><p class="long-note">Записи остаются в этом браузере. Экспорт включает профиль, замеры, блюда и тренировки. Для переноса на другой телефон сохрани файл и импортируй его там.</p><div class="flex wrap" style="margin-top:18px"><button type="button" class="btn soft small" data-action="export">${ico('download')}Резервная копия</button><button type="button" class="btn outline small" data-action="import">Восстановить</button></div><input type="file" id="import-file" accept="application/json,.json" class="hide"><p class="field-note">Экспортируй копию регулярно. Удаление данных браузера удалит локальную историю.</p></section></div></div></form>`}
function render(scroll=false){Object.assign(CLUBS,state.profile.clubNames||{});const opened=[...root.querySelectorAll('details[open][data-ex-detail]')].map(d=>d.dataset.exDetail);nav();root.innerHTML=({home,meals,training,habits,progress,guide,settings}[view]||home)();if(view==='training'){opened.forEach(id=>root.querySelector(`[data-ex-detail="${id}"]`)?.setAttribute('open',''));updateTimer()}if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function go(v){if(!['home','meals','training','habits','progress','guide','settings'].includes(v))return;view=v;if(v==='training')workout=trainingDay()||workout;render(true);location.hash=v}
function chooseDate(d){if(!validDate(d))return;selected=d;workout=trainingDay()||workout;render()}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(dateObj(s).getTime())&&localDate(dateObj(s))===s}
function dialog(title,body){modal.classList.toggle('product-dialog',body.includes('id="product-form"'));modal.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${ico('close')}</button></div>${body}`;modal.showModal()}
function swap(slot){dialog('Замена '+['завтрака','обеда','перекуса','ужина'][slot],`<p class="long-note">Выбери вариант. Меняется только этот приём выбранного дня. Отметка «съедено» сохранится.</p>${DATA.recipes.filter(r=>r.type===mealFor(slot).type).map(r=>{let m=macros(r.foods);return `<button class="choice" data-action="select-recipe" data-slot="${slot}" data-id="${r.id}"><strong>${esc(r.name)}</strong><span>≈${round(m[0])} ккал · Б ${round(m[1])} г · ${r.foods.map(([f])=>esc(f.split(',')[0])).join(', ')}</span></button>`}).join('')}`)}
function shopping(){let first=shift(selected,-dayIndex(selected)),tot={};for(let i=0;i<7;i++)for(let j=0;j<4;j++)for(let [f,g]of mealFor(j,shift(first,i)).foods)tot[f]=(tot[f]||0)+g;dialog('Покупки на неделю',`<p class="long-note">${esc(fmtDate(first))} — ${esc(fmtDate(shift(first,6)))}. По меню и изменённым порциям этой недели. Округли до удобных упаковок. Собственные дополнительные блюда не включены.</p><div style="margin-top:15px">${Object.entries(tot).map(([f,g])=>`<label class="shopping-row"><input type="checkbox" data-shopping="${esc(f)}" data-week="${first}" ${state.shopping[first+'-'+f]?'checked':''}><span>${esc(f)}</span><b>${g>=1000?num(g/1000,2)+' кг':round(g)+' г'}</b></label>`).join('')}</div>`)}
function customDialog(){dialog('Дополнительная еда',`<form id="custom-form"><label>Название<input name="name" required maxlength="100" placeholder="Например, мороженое"></label><div class="setting-grid" style="margin-top:15px"><label>Калории<input type="number" name="kcal" min="1" max="5000" required inputmode="numeric"></label><label>Белок, г<input type="number" name="p" min="0" max="300" step=".1" value="0" required inputmode="decimal"></label><label>Жиры, г<input type="number" name="f" min="0" max="300" step=".1" value="0" required inputmode="decimal"></label><label>Углеводы, г<input type="number" name="c" min="0" max="500" step=".1" value="0" required inputmode="decimal"></label></div><p class="field-note">На съеденную порцию, а не на 100 г. Возьми значения с упаковки. Запись сразу добавится к съеденному за день.</p><button class="btn" type="submit" style="width:100%">Добавить в дневник</button></form>`)}
function timerStart(seconds){timerEnd=Date.now()+seconds*1000;try{localStorage.setItem(KEY+'-timer',String(timerEnd))}catch{}updateTimer();if(!timerInterval)timerInterval=setInterval(updateTimer,500)}
function updateTimer(){const el=document.getElementById('timer-value');let t=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if(el)el.textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');if(timerEnd&&t===0){timerEnd=0;try{localStorage.removeItem(KEY+'-timer')}catch{}toast('Отдых закончен. Начинай следующий подход, когда готов.');if(timerInterval){clearInterval(timerInterval);timerInterval=null}}}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='forma-backup-'+TODAY+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Резервная копия готова')}
function validateBackup(x){if(!x||x.version!==1||!x.profile||!Array.isArray(x.measurements)||!x.days||typeof x.days!=='object')throw Error('Это не резервная копия ФОРМЫ');let o=structuredClone(defaults);let p=x.profile;for(let [k,a,b]of [['age',18,90],['height',130,230],['baseline',35,250],['kcal',1600,4000],['protein',80,240],['fat',45,140],['steps',0,25000],['water',500,4000],['dayA',0,6],['dayB',0,6]]){if(['age','height','baseline'].includes(k)&&p[k]===''){o.profile[k]='';continue}if(!Number.isFinite(p[k])||p[k]<a||p[k]>b)throw Error('Некорректный профиль');o.profile[k]=p[k]}if(!validDate(p.start))throw Error('Некорректная дата');o.profile.clubNames={club1:String(p.clubNames?.club1||'Зал 1').slice(0,80),club2:String(p.clubNames?.club2||'Зал 2').slice(0,80)};o.profile.start=p.start;o.profile.club=['club1','club2'].includes(p.club)?p.club:'club1';o.profile.notes=String(p.notes||'').slice(0,2000);o.profile.foodsNote=String(p.foodsNote||'').slice(0,1000);o.measurements=x.measurements.filter(m=>validDate(m.date)&&Number.isFinite(m.weight)&&m.weight>=35&&m.weight<=250).map(m=>({date:m.date,weight:m.weight,waist:Number.isFinite(m.waist)?m.waist:null,sleep:Number.isFinite(m.sleep)?m.sleep:null,note:String(m.note||'').slice(0,600)}));for(let [dt,d]of Object.entries(x.days)){if(!validDate(dt)||!d||typeof d!=='object')continue;let dd={meals:{},sets:{},water:clamp(Number(d.water)||0,0,10000),steps:clamp(Number(d.steps)||0,0,100000),cardio:clamp(Number(d.cardio)||0,0,180),custom:[],variants:{},club:['club1','club2'].includes(d.club)?d.club:'club1'};for(let i=0;i<4;i++){const m=d.meals?.[i];if(m&&recipe(m.id)){dd.meals[i]={id:m.id,done:!!m.done};if(Array.isArray(m.grams))dd.meals[i].grams=recipe(m.id).foods.map(([,g],j)=>Number.isFinite(m.grams[j])?clamp(m.grams[j],0,2000):g)}}for(let [k,v]of Object.entries(d.sets||{})){if(!/^[AB]-(?:(?:club1|club2)-)?(legpress|chest|row|legcurl|lateral|biceps|triceps|pulldown|pec)$/.test(k)||!Array.isArray(v))continue;dd.sets[k]=v.slice(0,5).map(s=>({kg:s.kg===''?'':clamp(Number(s.kg)||0,0,1000),reps:s.reps===''?'':clamp(Number(s.reps)||0,0,100),rir:s.rir===''?'':clamp(Number(s.rir)||0,0,10),done:!!s.done}))}dd.custom=(Array.isArray(d.custom)?d.custom:[]).slice(0,50).map(c=>({name:String(c.name||'Еда').slice(0,100),kcal:clamp(Number(c.kcal)||0,0,5000),p:clamp(Number(c.p)||0,0,300),f:clamp(Number(c.f)||0,0,300),c:clamp(Number(c.c)||0,0,500)}));for(let [k,v]of Object.entries(d.variants||{})){if(/^[AB]-(?:(?:club1|club2)-)?[a-z]+$/.test(k))dd.variants[k]=String(v).slice(0,150)}o.days[dt]=dd}for(let [k,c]of Object.entries(x.completed||{})){if(validDate(c.date)&&['A','B'].includes(c.workout))o.completed[c.date+'-'+c.workout+'-'+(['club1','club2'].includes(c.club)?c.club:'club1')]={date:c.date,workout:c.workout,club:['club1','club2'].includes(c.club)?c.club:'club1',sets:clamp(Number(c.sets)||0,0,50),cardio:clamp(Number(c.cardio)||0,0,180)}}for(let [k,v]of Object.entries(x.shopping||{})){if(k.length<200&&/^\d{4}-\d{2}-\d{2}-/.test(k))o.shopping[k]=!!v}return o}
function syncCompleted(){let key=completedKey();if(state.completed[key])state.completed[key].sets=ROUTINES[workout].reduce((n,id)=>n+(day().sets[setKey(id)]||[]).filter(s=>s.done).length,0)}
document.addEventListener('click',ev=>{const el=ev.target.closest('button,a,[data-date]');if(!el)return;if(el.dataset.nav){go(el.dataset.nav);return}if(el.dataset.date){chooseDate(el.dataset.date);return}if(el.dataset.workout){workout=el.dataset.workout;render();return}const a=el.dataset.action;if(!a)return;switch(a){case'date-prev':chooseDate(shift(selected,-1));break;case'date-next':chooseDate(shift(selected,1));break;case'toggle-meal':{let i=Number(el.dataset.slot),r=mealFor(i);day().meals[i]||={id:r.id};day().meals[i].done=!day().meals[i].done;save();render();break}case'save-steps':{let n=Number(document.getElementById('daily-steps').value);if(!Number.isFinite(n)||n<0||n>100000){toast('Введи шаги от 0 до 100 000');return}day().steps=round(n);save();toast('Шаги сохранены');break}case'water':day().water=clamp(day().water+Number(el.dataset.add),0,10000);save();render();break;case'swap':swap(Number(el.dataset.slot));break;case'select-recipe':{let i=Number(el.dataset.slot);day().meals[i]={id:el.dataset.id,done:!!day().meals[i]?.done};save();modal.close();render();toast('Блюдо заменено');break}case'shopping':shopping();break;case'custom-meal':customDialog();break;case'close-modal':modal.close();break;case'remove-custom':day().custom.splice(Number(el.dataset.index),1);save();render();break;case'timer':timerStart(Number(el.dataset.seconds));break;case'timer-stop':timerEnd=0;try{localStorage.removeItem(KEY+'-timer')}catch{}updateTimer();break;case'set-done':{let id=el.dataset.ex,i=Number(el.dataset.index),s=setData(id,i);if(!s.done&&(!Number.isFinite(Number(s.kg))||s.kg===''||!Number.isFinite(Number(s.reps))||Number(s.reps)<=0)){toast('Сначала запиши вес и повторения');return}s.done=!s.done;syncCompleted();save();render();if(s.done)timerStart(EXERCISES[id].rest);break}case'finish-workout':{let n=ROUTINES[workout].reduce((n,id)=>n+(day().sets[setKey(id)]||[]).filter(s=>s.done).length,0);if(!n){toast('Отметь хотя бы один выполненный подход');return}let cardio=Number(document.getElementById('cardio-minutes').value)||0;if(cardio<0||cardio>180){toast('Проверь длительность кардио');return}day().cardio=cardio;state.completed[completedKey()]={date:selected,workout,club:club(),sets:n,cardio};save();render();toast('Тренировка сохранена в истории');break}case'delete-measure':dialog('Удалить замер?',`<p>Запись за ${esc(fmtDate(el.dataset.dateId))} будет удалена.</p><button class="btn danger" data-action="confirm-delete-measure" data-date-id="${el.dataset.dateId}" style="margin-top:20px">Удалить запись</button>`);break;case'confirm-delete-measure':state.measurements=state.measurements.filter(m=>m.date!==el.dataset.dateId);save();modal.close();render();break;case'export':exportData();break;case'import':document.getElementById('import-file').click();break;case'confirm-import':if(window.pendingImport){state=window.pendingImport;delete window.pendingImport;save();modal.close();render();toast('История восстановлена')}break}});
document.addEventListener('change',async ev=>{let e=ev.target;if(e.id==='training-club'){day().club=e.value;state.profile.club=e.value;save();render();return}if(e.id==='selected-date'){chooseDate(e.value);return}if(e.dataset.portion!==undefined){let n=Number(e.value);if(!Number.isFinite(n)||n<0||n>2000){toast('Порция: от 0 до 2000 г');render();return}let i=Number(e.dataset.portion),r=mealFor(i);day().meals[i]||={id:r.id};day().meals[i].grams=r.foods.map(([,g])=>g);day().meals[i].grams[Number(e.dataset.food)]=n;save();render();return}if(e.dataset.set){let s=setData(e.dataset.set,Number(e.dataset.i)),n=e.value===''?'':Number(e.value),f=e.dataset.field,max=f==='kg'?1000:f==='reps'?100:10;if(n!==''&&(!Number.isFinite(n)||n<0||n>max)){toast('Проверь значение подхода');e.value=s[f];return}s[f]=n;save();return}if(e.dataset.variant){day().variants||={};day().variants[setKey(e.dataset.variant)]=e.value;save();return}if(e.dataset.shopping){state.shopping[e.dataset.week+'-'+e.dataset.shopping]=e.checked;save();return}if(e.id==='cardio-minutes'){let n=Number(e.value);if(Number.isFinite(n)&&n>=0&&n<=180){day().cardio=n;save()}return}if(e.id==='import-file'&&e.files[0]){try{let f=e.files[0];if(f.size>5e6)throw Error('Файл слишком большой');let imported=validateBackup(JSON.parse(await f.text()));window.pendingImport=imported;dialog('Восстановить историю?',`<p class="long-note">В копии: ${imported.measurements.length} замеров и ${Object.keys(imported.completed).length} тренировок. Она заменит текущие записи в этом браузере. Перед заменой можно закрыть окно и экспортировать текущую историю.</p><button class="btn" style="margin-top:20px" data-action="confirm-import">Заменить данными из копии</button>`)}catch(err){toast(err.message||'Не удалось прочитать копию')}e.value=''}});
document.addEventListener('submit',ev=>{ev.preventDefault();let form=ev.target,f=new FormData(form);if(form.id==='custom-form'){day().custom||=[];day().custom.push({name:String(f.get('name')).trim(),kcal:Number(f.get('kcal')),p:Number(f.get('p')),f:Number(f.get('f')),c:Number(f.get('c'))});save();modal.close();render();toast('Еда добавлена');return}if(form.id==='measure-form'){let m={date:selected,weight:Number(f.get('weight')),waist:f.get('waist')?Number(f.get('waist')):null,sleep:f.get('sleep')?Number(f.get('sleep')):null,note:String(f.get('note')).trim()};if(m.weight<35||m.weight>250)return;state.measurements=state.measurements.filter(x=>x.date!==selected);state.measurements.push(m);save();render();toast('Замер сохранён');return}if(form.id==='profile-form'){let p={...state.profile};for(let k of ['age','height','baseline','kcal','protein','fat','steps','water','dayA','dayB'])p[k]=Number(f.get(k));p.clubNames={club1:String(f.get('club1Name')||'Зал 1').slice(0,80),club2:String(f.get('club2Name')||'Зал 2').slice(0,80)};p.start=String(f.get('start'));p.notes=String(f.get('notes'));p.foodsNote=String(f.get('foodsNote'));let gap=Math.abs(p.dayA-p.dayB);if(gap===0||gap===1||gap===6){toast('Выбери дни с хотя бы одним днём отдыха между ними');return}if(p.protein*4+p.fat*9>p.kcal-200){toast('Слишком мало калорий остаётся на углеводы. Проверь БЖУ.');return}state.profile=p;save();render();toast('Профиль сохранён. Порции меню не менялись.')}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
window.addEventListener('hashchange',()=>{let v=location.hash.slice(1);if(['home','meals','training','habits','progress','guide','settings'].includes(v)&&v!==view){view=v;render(true)}});
Promise.all([fetch('data.json?v=health-recipes-130').then(r=>{if(!r.ok)throw Error('Данные недоступны');return r.json()}),loadRecoveryDatabase()]).then(([d,recovery])=>{if(recovery?.version===1&&recovery.profile&&recovery.days&&Array.isArray(recovery.measurements)&&(!readStoredState()||(recovery.savedAt||'')>(readStoredState().savedAt||''))){state={...structuredClone(defaults),...recovery,profile:{...defaults.profile,...recovery.profile}};persistedState=structuredClone(state);save()}DATA=d;view=['home','meals','training','habits','progress','guide','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'home';workout=trainingDay()||'A';render();if(timerEnd>Date.now())timerInterval=setInterval(updateTimer,500)}).catch(()=>{root.innerHTML='<div class="empty"><h2>Не удалось загрузить программу</h2><p>Проверь соединение и обнови страницу. Сохранённая история остаётся в браузере.</p><button class="btn" onclick="location.reload()" style="margin-top:20px">Обновить</button></div>'});
// Save edits on input as well as change: mobile keyboards may navigate before blur.
document.addEventListener('input',ev=>{const e=ev.target;if(!DATA)return;if(e.dataset.portion!==undefined){const n=Number(e.value);if(e.value===''||!Number.isFinite(n)||n<0||n>2000)return;const i=Number(e.dataset.portion),r=mealFor(i);day().meals[i]||={id:r.id};day().meals[i].grams=r.foods.map(([,g])=>g);day().meals[i].grams[Number(e.dataset.food)]=n;save();let card=e.closest('.meal-card'),m=macros(mealFor(i).foods);if(card)card.querySelector('.macro-mini').textContent=`≈${round(m[0])} ккал · Б ${round(m[1])} · Ж ${round(m[2])} · У ${round(m[3])} г`;let t=planned(),total=root.querySelector('.nutrition-total strong');if(total)total.innerHTML=round(t[0])+' <span>ккал</span>';let span=root.querySelector('.nutrition-total > span');if(span)span.innerHTML=`<b>Б ${round(t[1])}</b> / Ж ${round(t[2])} / У ${round(t[3])} г`}if(e.dataset.set){let f=e.dataset.field,n=e.value===''?'':Number(e.value),max=f==='kg'?1000:f==='reps'?100:10;if(n===''||(Number.isFinite(n)&&n>=0&&n<=max)){setData(e.dataset.set,Number(e.dataset.i))[f]=n;save()}}});

/* Tracker v2: explicit food diary, product library, water glasses and habits.
   All personal records stay in this browser. Only explicit product searches
   contact Open Food Facts. Recipe ideas never enter the diary automatically. */
const TRACKER_MEALS=['Завтрак','Обед','Ужин','Перекус','Другое'];
const HABIT_SEEDS=[['vegetables','Овощи и фрукты','Добавил овощи или фрукты в рацион'],['protein-meals','Белок в приёмах пищи','Продумал белковую часть основных приёмов'],['walk','Прогулка','Нашёл время пройтись в комфортном темпе'],['sleep','Восстановление','Оставил достаточно времени для сна']];
let foodTab='diary',foodMode='search',foodTarget='Завтрак',foodSelected=null,foodEditId=null,foodRequest=null,foodSession=0,scannerControls=null,scannerVideo=null,scannerNonce=0,lastFoodRemoved=null,lookupResults=[],productSearchQuery='',productLibraryMode='all';
const uid=prefix=>prefix+'-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));
function validBase(v,complete=true){return Array.isArray(v)&&v.length===4&&v.every((x,i)=>x===null?!complete:Number.isFinite(x)&&x>=0&&x<=(i?100:1000))}
function cleanProduct(p,complete=true){if(p?.id&&(!/^[a-zA-Z0-9_-]{1,120}$/.test(String(p.id))||['__proto__','constructor','prototype'].includes(p.id)))throw Error('Некорректный продукт в копии');if(!p||typeof p.name!=='string'||!p.name.trim()||!validBase(p.base,complete))throw Error('Проверь название и БЖУ продукта');return{id:String(p.id||uid('food')).slice(0,120),name:p.name.trim().slice(0,140),brand:String(p.brand||'').slice(0,100),barcode:String(p.barcode||'').replace(/\D/g,'').slice(0,14),base:p.base.slice(),unit:p.unit==='ml'?'ml':'g',source:['manual','openfoodfacts','builtin'].includes(p.source)?p.source:'manual',favorite:!!p.favorite}}
function seedProducts(){return Object.entries(DATA.foods).map(([name,base])=>{let h=2166136261;for(let c of name)h=Math.imul(h^c.charCodeAt(0),16777619);return{id:'base-'+(h>>>0).toString(16),name,base:base.slice(),unit:'g',source:'builtin',brand:'Типовые значения',favorite:!!state.products?.['base-'+(h>>>0).toString(16)]?.favorite}})}
function allProducts(){const map=new Map(seedProducts().map(p=>[p.id,p]));for(let p of Object.values(state.products||{}))map.set(p.id,p);return [...map.values()]}
function productById(id){return allProducts().find(p=>p.id===id)}
function entryMacros(e){let factor=e.kind==='portion'?e.amount:e.amount/100;return e.base.map(n=>n*factor)}
function trackerDay(s=selected){let d=day(s);d.entries||=[];d.habits||={};if(!Array.isArray(d.waterLogs)){d.waterLogs=d.water>0?[{id:uid('water-old'),amount:Number(d.water),at:'',label:'Ранее записанный объём'}]:[]}if(d.trackerVersion!==2&&DATA){for(let i=0;i<4;i++)if(d.meals?.[i]?.done){let r=mealFor(i,s);d.entries.push({id:uid('legacy-meal'),kind:'portion',name:r.name,base:macros(r.foods),amount:1,unit:'portion',meal:r.type,source:'legacy',at:''})}for(let c of d.custom||[])d.entries.push({id:uid('legacy-food'),kind:'portion',name:String(c.name),base:[Number(c.kcal)||0,Number(c.p)||0,Number(c.f)||0,Number(c.c)||0],amount:1,unit:'portion',meal:'Другое',source:'legacy',at:''});d.trackerVersion=2}d.water=d.waterLogs.reduce((n,w)=>n+w.amount,0);return d}
function ensureTracker(){if(!DATA)return;if(state.trackerVersion!==2){try{let raw=localStorage.getItem(KEY)||localStorage.getItem('forma-public-personal-v1');if(raw&&!localStorage.getItem(KEY+'-before-tracker-v2'))localStorage.setItem(KEY+'-before-tracker-v2',raw)}catch{}state.products||={};state.habitDefs||=HABIT_SEEDS.map(([id,name,desc])=>({id,name,desc,created:state.profile.start||TODAY,archived:null}));state.profile.glassSize||=250;for(let dt of Object.keys(state.days))trackerDay(dt);state.trackerVersion=2;save()}state.products||={};state.habitDefs||=[];state.profile.glassSize||=250;trackerDay()}
const originalTrackerRender=render;
render=function(scroll=false){ensureTracker();originalTrackerRender(scroll)};
eaten=function(s=selected){return sum(trackerDay(s).entries.map(entryMacros))};
NAV.splice(3,0,['habits','Привычки','check']);
function diaryStats(s=selected){let d=trackerDay(s),v=eaten(s);return{count:d.entries.length,meals:new Set(d.entries.map(e=>e.meal)).size,values:v}}
function compactDiary(){let d=trackerDay();return `<section class="card"><div class="flex between"><h3>Мой дневник питания</h3><button class="text-link" data-nav="meals">Открыть ${ico('right')}</button></div>${d.entries.length?d.entries.slice(-4).reverse().map(e=>`<div class="meal-line"><div class="meal-icon">${ico('food')}</div><div class="meal-copy"><small>${esc(e.meal)}</small><h3>${esc(e.name)}</h3><small>${portionLabel(e)} · ${round(entryMacros(e)[0])} ккал</small></div></div>`).join(''):`<div class="diary-empty"><div class="meal-icon">${ico('food')}</div><h3>Что сегодня на тарелке?</h3><p>Добавь продукт из базы, по штрихкоду или с этикетки. Меню остаётся источником идей.</p></div>`}<button class="btn" style="width:100%;margin-top:15px" data-tracker="add-food">${ico('plus')}Записать продукт</button></section>`}
function portionLabel(e){return num(e.amount,1)+' '+(e.kind==='portion'?'порц.':e.unit==='ml'?'мл':'г')}
function glassSvg(full=false){return `<svg viewBox="0 0 44 54" fill="none" aria-hidden="true"><path d="M8 5h28l-3.6 42a3 3 0 0 1-3 2.7H14.6a3 3 0 0 1-3-2.7L8 5Z" fill="${full?'#8ab8da':'#f3f8fc'}" stroke="${full?'#3980ad':'#b5cfdf'}" stroke-width="1.5"/><path d="M10 23c8-4 15 4 24 0l-2 23H12l-2-23Z" fill="${full?'#4c9acb':'#e2edf5'}"/><path d="M14 10l2 28" stroke="white" stroke-width="2" stroke-linecap="round" opacity=".8"/>${full?'<path d="m16 30 5 5 8-10" stroke="white" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/>':''}</svg>`}
function waterPanel(full=false){const d=trackerDay(),size=state.profile.glassSize||250,count=Math.min(24,Math.max(4,Math.ceil(state.profile.water/size))),total=d.water,goal=state.profile.water,glasses=total/size;return `<section class="card water-panel"><div class="flex between"><div><div class="eyebrow">ВОДА В ТЕЧЕНИЕ ДНЯ</div><h3>${full?'Твой водный баланс':'Стакан за стаканом'}</h3></div><span class="water-drop">${ico('drop')}</span></div><div class="water-metric">${num(total/1000,2)} <span>/ ${num(goal/1000,2)} л</span></div><p class="muted" style="font-size:12px">${num(glasses,1)} стак. по ${size} мл · ${Math.min(100,round(total/goal*100))}% ориентира</p><div class="glass-grid">${Array.from({length:count},(_,i)=>{let log=d.waterLogs.find(w=>w.id==='glass-'+i);return `<button class="glass-button ${log?'filled':''}" data-tracker="glass" data-glass="${i}" aria-label="Стакан ${i+1}${log?': убрать отметку':': отметить '+size+' мл'}" aria-pressed="${!!log}">${glassSvg(!!log)}<span>${i+1}</span></button>`}).join('')}</div><div class="flex wrap water-actions"><button class="btn small water-primary" data-tracker="add-glass">${ico('plus')}Стакан ${size} мл</button><button class="btn small outline" data-tracker="water-custom">Другой объём</button><button class="icon-btn" data-tracker="glass-size" aria-label="Настроить размер стакана">${ico('settings')}</button></div><div class="track water-track"><i style="width:${clamp(total/goal*100,0,100)}%"></i></div><p class="field-note">Нажми на стакан, чтобы отметить воду. Повторное нажатие снимает его отметку. Записанный объём сохраняется, даже если позже изменить размер стакана.</p>${full?`<details class="water-history"><summary>Записи за день (${d.waterLogs.length})</summary>${d.waterLogs.length?d.waterLogs.slice().reverse().map(w=>`<div class="water-log"><div><b>${num(w.amount)} мл</b><small>${esc(w.label||'Вода')}${w.at?' · '+new Date(w.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):''}</small></div><button class="icon-btn" data-tracker="remove-water" data-id="${esc(w.id)}" aria-label="Удалить запись воды ${w.amount} мл">${ico('close')}</button></div>`).join(''):'<p class="long-note">Пока нет записей.</p>'}</details><p class="tip">Ориентир можно изменить в профиле. Пей по жажде с учётом жары и активности. Чай, кофе и вода из еды тоже дают жидкость; их калории записывай отдельно в питании. Медицинские ограничения важнее цифры.</p>`:''}</section>`}
home=function(){const tr=trainingDay(),ds=diaryStats(),hs=habitSummary();return head('Твой здоровый день','Питание, привычки, вода и движение — в одном дневнике.')+weekStrip()+`${!state.profile.baseline?'<div class="info-strip">Личные параметры сохраняются на этом устройстве. <button class="text-link" data-nav="settings">Настроить профиль</button></div>':''}<section class="hero tracker-hero"><div class="hero-copy"><div class="eyebrow">МАЛЕНЬКИЕ ДЕЙСТВИЯ КАЖДЫЙ ДЕНЬ</div><h2>Забота о себе.<br>В твоём ритме.</h2><p>Отмечай то, что сделал. Рацион можно собрать из любимой еды, а пример меню оставить для вдохновения.</p><div class="hero-metrics"><div><b>${num(state.profile.kcal)}</b><small>ккал — ориентир</small></div><div><b>${hs.done}/${hs.total}</b><small>привычек сегодня</small></div></div><button class="btn lime small" data-tracker="add-food">${ico('plus')}Записать еду</button></div><div class="hero-photo" role="img" aria-label="Тарелка с разнообразной едой"></div></section><div class="section-head"><h2>Что уже съедено</h2><span class="tag">${ds.count} записей</span></div>${macroCards()}<div class="grid layout-main" style="margin-top:21px"><div class="grid">${compactDiary()}<section class="card"><div class="flex between"><h3>${tr?'Сегодня фуллбоди '+tr:'Движение и восстановление'}</h3>${ico(tr?'gym':'walk')}</div><p class="long-note" style="margin-top:12px">${tr?'Умеренный объём, упражнения на тренажёрах и запас повторений. Вес и подходы записываются отдельно для каждого зала.':'Привычная ходьба в комфортном темпе. Сегодня можно уделить внимание отдыху и сну.'}</p><div class="inline-input" style="margin-top:14px"><label style="flex:1">Шаги за день<input id="daily-steps" type="number" min="0" max="100000" inputmode="numeric" value="${esc(trackerDay().steps)}" placeholder="Ориентир: ${state.profile.steps}"></label><button class="icon-btn" data-action="save-steps" aria-label="Сохранить шаги">${ico('check')}</button></div><div id="walking-calories">${walkingCaloriesPanel()}</div><div class="step-refresh">${bridgeConfig()?`<a class="btn small" href="shortcuts://run-shortcut?name=${encodeURIComponent(state.profile.healthShortcutName||'ФОРМА Шаги')}">${ico('walk')}Обновить шаги</a><p class="field-note">Откроется команда «ФОРМА Шаги» на iPhone.</p>`:`<button class="btn small" data-steps="setup">${ico('walk')}Подключить шаги с iPhone</button>`}</div><button class="btn small soft" data-nav="${tr?'training':'habits'}">${tr?'Открыть тренировку':'Мои привычки'}${ico('arrow')}</button></section></div><div class="grid">${waterPanel()}<section class="card"><div class="flex between"><h3>Мои привычки</h3><button class="text-link" data-nav="habits">Все ${ico('right')}</button></div>${habitRows(false)}<div class="track"><i style="width:${hs.total?hs.done/hs.total*100:0}%"></i></div><small>${hs.done} из ${hs.total} действий на сегодня</small></section></div></div>`};
function diaryEntryRow(e){let v=entryMacros(e);return `<div class="diary-entry"><button class="entry-edit" data-tracker="edit-entry" data-id="${esc(e.id)}"><strong>${esc(e.name)}</strong><small>${portionLabel(e)}${e.brand?' · '+esc(e.brand):''}</small><span>Б ${num(v[1],1)} · Ж ${num(v[2],1)} · У ${num(v[3],1)} г</span></button><div class="entry-right"><b>${round(v[0])}</b><small>ккал</small><button class="icon-btn" data-tracker="delete-entry" data-id="${esc(e.id)}" aria-label="Удалить ${esc(e.name)}">${ico('close')}</button></div></div>`}
function recipeIdeaCard(i){let r=mealFor(i),m=macros(r.foods);return `<article class="card idea-card"><div class="eyebrow">${r.type} · ПРИМЕР</div><h3>${esc(r.name)}</h3><div class="macro-mini">≈${round(m[0])} ккал · Б ${round(m[1])} · Ж ${round(m[2])} · У ${round(m[3])} г</div><div class="idea-foods">${r.foods.map(([f,g])=>`<div class="ingredient"><span>${esc(f)}</span><b>${g} г</b></div>`).join('')}</div><p class="long-note">${esc(r.method)}</p><button class="btn soft small" data-tracker="log-recipe" data-slot="${i}">${ico('plus')}Записать съеденную порцию</button></article>`}
meals=function(){const d=trackerDay();return head('Твой дневник питания','Записывай реальные продукты. Пример меню больше не считается съеденной едой.')+weekStrip()+`<div class="food-nav"><div class="workout-tabs"><button class="${foodTab==='diary'?'active':''}" data-food-tab="diary">Мой дневник</button><button class="${foodTab==='ideas'?'active':''}" data-food-tab="ideas">Идеи меню</button></div><button class="btn" data-tracker="add-food">${ico('plus')}Добавить продукт</button></div>${foodTab==='ideas'?`<div class="info-strip">Пример рациона около 2000 ккал. Можно взять отдельное блюдо или просто идею. В дневник ничего не попадает без твоего действия. Мясо и рыба — сырые, крупы — сухие. <button class="text-link" data-action="shopping">Покупки по примеру меню</button></div><div class="grid two">${[0,1,2,3].map(recipeIdeaCard).join('')}</div>`:`${macroCards()}${lastFoodRemoved&&lastFoodRemoved.date===selected?'<div class="info-strip">Запись удалена. <button class="text-link" data-tracker="undo-food">Вернуть</button></div>':''}<div class="diary-groups">${TRACKER_MEALS.map(meal=>{let es=d.entries.filter(e=>e.meal===meal);return `<section class="card diary-group"><div class="flex between"><div><h3>${meal}</h3><small>${es.length?round(sum(es.map(entryMacros))[0])+' ккал':'Пока нет записей'}</small></div><button class="text-link" data-tracker="add-food" data-meal="${meal}">${ico('plus')}Добавить</button></div>${es.map(diaryEntryRow).join('')}${!es.length?`<button class="add-entry-empty" data-tracker="add-food" data-meal="${meal}">Продукт, штрихкод или своё блюдо</button>`:''}</section>`}).join('')}</div><p class="long-note">Нажми на продукт, чтобы изменить порцию. Значения из базы приблизительные: сверяй их с этикеткой и выбирай правильный вариант «сырой / готовый».</p>`}`};
function activeHabits(s=selected){return state.habitDefs.filter(h=>h.created<=s&&(!h.archived||h.archived>s))}
function autoHabits(s=selected){let d=trackerDay(s),v=eaten(s),a=[{id:'auto-water',name:'Вода по ориентиру',desc:num(d.water/1000,2)+' / '+num(state.profile.water/1000,2)+' л',done:d.water>=state.profile.water},{id:'auto-protein',name:'Белок по ориентиру',desc:round(v[1])+' / '+state.profile.protein+' г',done:v[1]>=state.profile.protein}];if(state.profile.steps>0)a.push({id:'auto-steps',name:'Шаги по ориентиру',desc:(d.steps===''?'Нет записи':num(d.steps))+' / '+num(state.profile.steps),done:Number(d.steps)>=state.profile.steps});if(trainingDay(s)){const record=Object.values(state.completed).find(c=>c.date===s);a.push({id:'auto-training',name:'Тренировка записана',desc:record?'Фуллбоди '+record.workout+' сохранена':'Сегодня по плану фуллбоди '+trainingDay(s),done:!!record})}return a}
function habitSummary(s=selected){let d=trackerDay(s),manual=activeHabits(s),auto=autoHabits(s);return{done:manual.filter(h=>d.habits[h.id]).length+auto.filter(h=>h.done).length,total:manual.length+auto.length}}
function habitRows(full=true){const d=trackerDay(),list=activeHabits();return list.slice(0,full?40:3).map(h=>`<div class="habit-row"><button class="habit-check ${d.habits[h.id]?'done':''}" data-tracker="habit-toggle" data-id="${esc(h.id)}" aria-label="${esc(h.name)}" aria-pressed="${!!d.habits[h.id]}">${d.habits[h.id]?ico('check'):''}</button><div><strong>${esc(h.name)}</strong>${full?`<small>${esc(h.desc||'Отметь, когда сделаешь')}</small>`:''}</div></div>`).join('')}
function habits(){const hs=habitSummary(),first=shift(selected,-dayIndex(selected));return head('Привычки, которые остаются','Отмечай действия без гонки за идеальными днями.')+weekStrip()+`<section class="card habit-week"><div class="flex between"><h3>Твоя неделя</h3><span class="tag">${hs.done}/${hs.total} сегодня</span></div><div class="habit-heatmap">${Array.from({length:7},(_,i)=>{let dt=shift(first,i),exists=!!state.days[dt],h=exists?habitSummary(dt):{done:0,total:activeHabits(dt).length+3};return `<button class="heat-day ${dt===selected?'selected':''} ${h.done&&h.done===h.total?'all-done':''}" data-date="${dt}"><small>${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'][i]}</small><b>${exists?h.done:'—'}</b><span>${exists?'из '+h.total:'нет записей'}</span></button>`}).join('')}</div><p class="field-note">Автоматические отметки воды, белка, шагов и зала рассчитываются по записям и текущим ориентирам профиля. Пропуск дня не обнуляет историю.</p></section><div class="grid two" style="margin-top:20px"><div>${waterPanel(true)}</div><div class="grid"><section class="card"><div class="flex between"><h3>Что сделано сегодня</h3><button class="text-link" data-tracker="manage-habits">Настроить</button></div>${habitRows(true)}<button class="btn small soft" data-tracker="new-habit" style="margin-top:15px">${ico('plus')}Своя привычка</button></section><section class="card"><div class="eyebrow">СЧИТАЕМ ПО ЗАПИСЯМ</div><h3>Отмечается автоматически</h3>${autoHabits().map(h=>`<div class="habit-row auto"><div class="habit-check ${h.done?'done':''}">${h.done?ico('check'):ico('chart')}</div><div><strong>${h.name}</strong><small>${h.desc}</small></div>${h.done?'<span class="tag">Готово</span>':''}</div>`).join('')}<p class="tip">Это ориентиры для наблюдения. Не нужно пить через силу или доедать только ради зелёной отметки.</p></section></div></div>`}
function setWaterTotal(){let d=trackerDay();d.water=d.waterLogs.reduce((n,w)=>n+w.amount,0)}
function addWater(amount,id=null){let d=trackerDay();if(d.water+amount>10000){toast('Проверь объём воды: сумма превышает 10 литров');return}d.waterLogs.push({id:id||uid('water'),amount,at:new Date().toISOString(),label:amount===(state.profile.glassSize||250)?'Мой стакан':'Вода'});setWaterTotal();save();render()}
function habitDialog(){dialog('Мои привычки',`<p class="long-note">Привычка скроется с выбранной даты и останется в истории прошлых дней. Автоматические ориентиры настраиваются в профиле.</p>${activeHabits().map(h=>`<div class="flex between habit-manage"><strong>${esc(h.name)}</strong><button class="btn small outline" data-tracker="archive-habit" data-id="${esc(h.id)}">Скрыть</button></div>`).join('')}<button class="btn soft" data-tracker="new-habit" style="margin-top:16px">${ico('plus')}Добавить привычку</button>`)}
function addHabitDialog(){dialog('Новая привычка',`<form id="habit-form"><label>Название<input name="habitName" required maxlength="80" placeholder="Например, ужин без телефона"></label><label style="margin-top:15px">Подсказка · необязательно<input name="habitDesc" maxlength="180" placeholder="Какое действие хочешь отмечать?"></label><button class="btn" type="submit" style="width:100%;margin-top:18px">Добавить</button></form>`)}
function localProductResults(q=''){const words=q.toLocaleLowerCase('ru').trim().split(/\s+/).filter(Boolean);let list=allProducts().filter(p=>words.every(w=>(p.name+' '+p.brand+' '+p.barcode).toLocaleLowerCase('ru').includes(w)));if(productLibraryMode==='favorites')list=list.filter(p=>p.favorite);if(productLibraryMode==='mine')list=list.filter(p=>p.source==='manual');return list.sort((a,b)=>Number(b.favorite)-Number(a.favorite)||a.name.localeCompare(b.name,'ru')).slice(0,35)}
function productRow(p,remote=false){const complete=validBase(p.base);return `<div class="product-result"><button class="product-pick" data-tracker="select-product" data-product="${esc(p.id)}" data-remote="${remote?'1':'0'}"><strong>${esc(p.name)}</strong><small>${esc(p.brand||sourceLabel(p.source))}${p.barcode?' · '+esc(p.barcode):''}</small><span>${complete?`${round(p.base[0])} ккал · Б ${num(p.base[1],1)} · Ж ${num(p.base[2],1)} · У ${num(p.base[3],1)} на 100 ${p.unit==='ml'?'мл':'г'}`:'Данные неполные — можно заполнить с этикетки'}</span></button>${remote?'':`<button class="favorite-btn ${p.favorite?'is-favorite':''}" data-tracker="favorite-product" data-product="${esc(p.id)}" aria-label="${p.favorite?'Убрать из избранного':'В избранное'}: ${esc(p.name)}" aria-pressed="${p.favorite}">${p.favorite?'★':'☆'}</button>`}</div>`}
function sourceLabel(s){return s==='openfoodfacts'?'Open Food Facts':s==='builtin'?'Базовые продукты · примерно':'Мой продукт'}
function updateLocalResults(){const box=document.getElementById('local-food-results');if(!box)return;let found=localProductResults(productSearchQuery);box.innerHTML=found.length?found.map(p=>productRow(p)).join(''):'<div class="empty">Ничего не найдено. Попробуй общую базу или создай продукт по этикетке.</div>'}
function stopFoodRequest(){if(foodRequest){foodRequest.abort();foodRequest=null}}
function foodPicker(meal=null){stopCamera();stopFoodRequest();foodSession++;foodSelected=null;foodEditId=null;foodTarget=TRACKER_MEALS.includes(meal)?meal:(new Date().getHours()<11?'Завтрак':new Date().getHours()<17?'Обед':'Ужин');foodMode='search';productSearchQuery='';productLibraryMode='all';showFoodPicker()}
function showFoodPicker(){foodSelected=null;let inner=foodMode==='barcode'?`<form id="barcode-form"><label>Штрихкод с упаковки<input name="barcode" id="barcode-input" inputmode="numeric" autocomplete="off" maxlength="24" placeholder="8, 12, 13 или 14 цифр"></label><div class="flex wrap" style="margin-top:12px"><button class="btn" type="submit">Найти продукт</button><button class="btn soft" type="button" data-tracker="start-camera">${ico('scan')}Сканировать</button></div></form><div id="scanner-area"></div><div id="remote-food-status" role="status"></div><div id="remote-food-results"></div><p class="field-note">Код отправится в Open Food Facts. Камера включается только по кнопке, изображение обрабатывается на устройстве.</p>`:`<form id="food-search-form"><label>Название продукта или бренд<input id="product-query" name="query" autocomplete="off" maxlength="100" placeholder="Например, творог или гречка" value="${esc(productSearchQuery)}"></label><button class="btn soft" type="submit" style="width:100%;margin-top:10px">Поиск в Open Food Facts</button></form><div class="library-tabs"><button class="${productLibraryMode==='all'?'active':''}" data-tracker="library-filter" data-filter="all">Базовые и мои</button><button class="${productLibraryMode==='favorites'?'active':''}" data-tracker="library-filter" data-filter="favorites">★ Избранное</button><button class="${productLibraryMode==='mine'?'active':''}" data-tracker="library-filter" data-filter="mine">Свои продукты</button></div><div id="local-food-results"></div><div id="remote-food-status" role="status"></div><div id="remote-food-results"></div>`;
 if(modal.open)modal.close();dialog('Добавить еду',`<div class="food-target">${esc(fmtDate(selected))} · ${esc(foodTarget)}</div><div class="food-mode-tabs"><button class="${foodMode==='search'?'active':''}" data-tracker="food-mode" data-mode="search">По названию</button><button class="${foodMode==='barcode'?'active':''}" data-tracker="food-mode" data-mode="barcode">Штрихкод</button><button data-tracker="manual-product">Вручную</button></div>${inner}<p class="database-note"><a href="https://world.openfoodfacts.org/" target="_blank" rel="noopener">Open Food Facts</a> (ODbL). Данные добавляют пользователи. Перед записью сверь БЖУ и единицы с упаковкой. Дневник и медицинские заметки в базу не отправляются.</p>`);if(foodMode==='search')updateLocalResults();}
ICONS.scan='<path d="M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5M7 7v10M10 7v10M14 7v10M17 7v10"/>';
function normalizeOFF(p){const n=p.nutriments||{},value=k=>{let v=n[k];return v===undefined||v===null||v===''?null:Number.isFinite(Number(v))?Number(v):null};let kcal=value('energy-kcal_100g');if(kcal===null&&value('energy-kj_100g')!==null)kcal=value('energy-kj_100g')/4.184;let base=[kcal,value('proteins_100g'),value('fat_100g'),value('carbohydrates_100g')].map((v,i)=>v!==null&&v>=0&&v<=(i?100:1000)?v:null);return cleanProduct({id:'off-'+String(p.code||uid('unknown')),name:p.product_name_ru||p.product_name||p.generic_name_ru||p.generic_name||'Продукт без названия',brand:p.brands||'',barcode:p.code||'',base,unit:'g',source:'openfoodfacts'},false)}
async function fetchFood(url){stopFoodRequest();const controller=new AbortController();foodRequest=controller;const timer=setTimeout(()=>controller.abort(),22000);try{for(let attempt=0;attempt<2;attempt++){try{let r=await fetch(url,{signal:controller.signal,credentials:'omit',referrerPolicy:'strict-origin-when-cross-origin'});if(!r.ok){if(r.status===404){try{const absent=await r.json();if(absent.status===0)return absent}catch{}throw Error('Продукт или страница базы не найдены.')}if(r.status>=500&&attempt===0){await new Promise(resolve=>setTimeout(resolve,800));continue}throw Error(r.status===429?'База временно ограничила запросы. Попробуй позже.':'База сейчас недоступна. Можно добавить продукт вручную.')}try{return await r.json()}catch{throw Error('База вернула неожиданный ответ. Попробуй позже или добавь продукт вручную.')}}catch(e){if(e.name==='TypeError'&&attempt===0&&!controller.signal.aborted){await new Promise(resolve=>setTimeout(resolve,800));continue}if(e.name==='TypeError')throw Error('Нет связи с общей базой. Локальные продукты и ручной ввод доступны.');throw e}}}finally{clearTimeout(timer);if(foodRequest===controller)foodRequest=null}}
function remoteStatus(msg,error=false){let el=document.getElementById('remote-food-status');if(el){el.className='remote-status'+(error?' error':'');el.textContent=msg}}
async function lookupBarcode(raw){let code=String(raw||'').replace(/[\s-]/g,'');if(!/^(?:\d{8}|\d{12}|\d{13}|\d{14})$/.test(code)){remoteStatus('Введи 8, 12, 13 или 14 цифр с упаковки.',true);return}let existing=Object.values(state.products).find(p=>p.barcode===code);if(existing){productReview(existing);return}let session=++foodSession;remoteStatus('Ищем продукт по штрихкоду…');let resultBox=document.getElementById('remote-food-results');if(resultBox)resultBox.innerHTML='';try{let fields='code,product_name,product_name_ru,generic_name,brands,nutriments';let data=await fetchFood('https://world.openfoodfacts.org/api/v2/product/'+encodeURIComponent(code)+'.json?fields='+fields+'&app_name=FormaTracker&app_version=2');if(!modal.open||session!==foodSession)return;if(data.status===0||!data.product){remoteStatus('Этого продукта пока нет в базе. Можно записать его с этикетки.');resultBox.innerHTML='<button class="btn soft" data-tracker="manual-product" data-barcode="'+esc(code)+'">Создать продукт с этим кодом</button>';return}let p=normalizeOFF({...data.product,code});lookupResults=[p];productReview(p)}catch(e){if(session!==foodSession||!modal.open)return;remoteStatus(e.name==='AbortError'?'Запрос занял слишком много времени. Попробуй ещё раз или добавь вручную.':e.message||'Нет связи с базой. Добавь продукт вручную.',true);resultBox.innerHTML='<button class="btn soft" data-tracker="manual-product" data-barcode="'+esc(code)+'">Ввести с этикетки</button>'}}
async function searchRemoteFoods(q){q=String(q||'').trim();if(q.length<3){remoteStatus('Для общей базы введи хотя бы 3 символа.',true);return}let session=++foodSession;remoteStatus('Ищем в Open Food Facts…');let resultBox=document.getElementById('remote-food-results');resultBox.innerHTML='';try{let params=new URLSearchParams({search_terms:q,json:'1',page_size:'15',lc:'ru',fields:'code,product_name,product_name_ru,generic_name,brands,nutriments',app_name:'FormaTracker',app_version:'2'});let data;try{data=await fetchFood('https://search.openfoodfacts.org/search?'+new URLSearchParams({q,page_size:'15',fields:'code,product_name,brands,nutriments',langs:'ru,en'}))}catch(primaryError){if(!modal.open||session!==foodSession)return;data=await fetchFood('https://world.openfoodfacts.org/cgi/search.pl?'+params)}if(!modal.open||session!==foodSession)return;lookupResults=(data.products||data.hits||[]).map(p=>{try{return normalizeOFF(p)}catch{return null}}).filter(Boolean);remoteStatus(lookupResults.length?'Общая база: '+lookupResults.length+' результатов.':'В общей базе ничего не найдено. Попробуй другой запрос или ручной ввод.');resultBox.innerHTML=lookupResults.map(p=>productRow(p,true)).join('')}catch(e){if(session!==foodSession||!modal.open)return;remoteStatus(e.name==='AbortError'?'Поиск занял слишком много времени. Локальные продукты и ручной ввод доступны.':e.message||'Нет связи с общей базой.',true)}}
function productReview(p=null){stopCamera();stopFoodRequest();foodSession++;foodSelected=p?{...p,base:p.base.slice()}:{id:uid('manual'),name:productSearchQuery||'',brand:'',barcode:'',base:[null,null,null,null],unit:'g',source:'manual',favorite:false};foodEditId=null;showProductForm()}
function showProductForm(){let p=foodSelected,entry=foodEditId?trackerDay().entries.find(e=>e.id===foodEditId):null;if(modal.open)modal.close();dialog(entry?'Изменить запись':'Продукт и порция',`<form id="product-form"><div class="product-fields"><div class="review-source">${esc(sourceLabel(p.source))}${p.barcode?' · '+esc(p.barcode):''}</div><label>Название<input name="name" required maxlength="140" value="${esc(p.name)}" placeholder="Название с упаковки"></label><div class="setting-grid" style="margin-top:13px"><label>Бренд · необязательно<input name="brand" maxlength="100" value="${esc(p.brand)}"></label><label>Штрихкод · необязательно<input name="barcode" inputmode="numeric" maxlength="14" value="${esc(p.barcode)}"></label></div><div class="nutri-label"><h3>Пищевая ценность на 100</h3><select name="unit" id="food-unit" aria-label="Единицы пищевой ценности"><option value="g" ${p.unit!=='ml'?'selected':''}>граммов</option><option value="ml" ${p.unit==='ml'?'selected':''}>миллилитров</option></select></div><div class="nutrition-inputs">${[['Калории, ккал','kcal',0,1000],['Белки, г','p',1,100],['Жиры, г','f',2,100],['Углеводы, г','c',3,100]].map(([label,k,i,max])=>`<label>${label}<input type="number" name="${k}" data-nutri="${k}" inputmode="decimal" min="0" max="${max}" step="any" required value="${p.base[i]===null?'':p.base[i]}" placeholder="С этикетки"></label>`).join('')}</div><p class="field-note">${p.source==='builtin'?'Для обычных продуктов это типовые значения. Упаковка имеет приоритет.':'Если поле пустое, данных в базе не хватило: заполни его по этикетке.'} Выбирай «мл» только если значения на упаковке даны на 100 мл. Перевод между граммами и миллилитрами не выполняется.</p><div class="setting-grid"><label>Съеденная порция<input name="amount" id="food-amount" type="number" min="0.1" max="5000" step="any" inputmode="decimal" required value="${entry?.amount||100}"></label><label>Приём пищи<select name="meal">${TRACKER_MEALS.map(m=>`<option ${m===(entry?.meal||foodTarget)?'selected':''}>${m}</option>`).join('')}</select></label></div><div id="portion-preview" class="portion-preview"></div></div><div class="product-save-bar"><button class="btn" type="submit" style="width:100%">${ico('check')}${entry?'Сохранить запись':'Сохранить продукт и добавить'}</button><button type="button" class="text-link" data-tracker="back-to-food" style="margin-top:10px">Вернуться к поиску</button></div></form>`);updatePortionPreview()}
function updatePortionPreview(){const form=document.getElementById('product-form');if(!form)return;const f=new FormData(form),base=['kcal','p','f','c'].map(k=>f.get(k)===''?null:Number(f.get(k))),amount=Number(f.get('amount')),box=document.getElementById('portion-preview');if(!validBase(base)||!Number.isFinite(amount)||amount<=0){box.textContent='Заполни калории, БЖУ и порцию — здесь появится расчёт.';return}let v=base.map(n=>n*amount/100);box.innerHTML=`<b>${round(v[0])} ккал</b><span>Б ${num(v[1],1)} · Ж ${num(v[2],1)} · У ${num(v[3],1)} г</span><small>На ${num(amount,1)} ${f.get('unit')==='ml'?'мл':'г'} съеденной порции</small>`}
function editDiaryEntry(id){const e=trackerDay().entries.find(e=>e.id===id);if(!e)return;if(e.kind==='portion'){dialog('Изменить порцию',`<form id="portion-entry-form"><p><b>${esc(e.name)}</b></p><input name="entryId" type="hidden" value="${esc(e.id)}"><div class="setting-grid" style="margin-top:18px"><label>Порций<input name="amount" type="number" min="0.1" max="20" step="any" inputmode="decimal" value="${e.amount}" required></label><label>Приём пищи<select name="meal">${TRACKER_MEALS.map(m=>`<option ${m===e.meal?'selected':''}>${m}</option>`).join('')}</select></label></div><p class="field-note">Значения сохранены на одну порцию готового блюда. Для отдельных продуктов используй запись с граммовкой.</p><button class="btn" type="submit">Сохранить</button></form>`);return}foodSelected={id:e.productId||uid('manual'),name:e.name,brand:e.brand||'',barcode:e.barcode||'',base:e.base.slice(),unit:e.unit,source:e.source||'manual',favorite:!!state.products[e.productId]?.favorite};foodEditId=id;showProductForm()}
function logRecipe(slot){let r=mealFor(slot),m=macros(r.foods);dialog('Записать блюдо из примера',`<form id="recipe-entry-form"><input type="hidden" name="slot" value="${slot}"><h3>${esc(r.name)}</h3><p class="long-note" style="margin-top:10px">Одна порция из примера: ${round(m[0])} ккал, Б ${round(m[1])} / Ж ${round(m[2])} / У ${round(m[3])} г. Если состав или граммовки отличаются, добавь фактические продукты отдельно.</p><label style="margin-top:18px">Сколько порций съел?<input name="amount" type="number" min="0.1" max="10" step="any" inputmode="decimal" value="1" required></label><button type="submit" class="btn" style="width:100%;margin-top:18px">Добавить в дневник</button></form>`)}
function loadScanner(){if(window.ZXingBrowser)return Promise.resolve();return new Promise((resolve,reject)=>{const old=document.getElementById('zxing-library');if(old){old.addEventListener('load',resolve,{once:true});old.addEventListener('error',reject,{once:true});return}let script=document.createElement('script');script.id='zxing-library';script.src='vendor/zxing-browser-0.1.5.min.js';script.onload=resolve;script.onerror=()=>{script.remove();reject(Error('Не удалось загрузить сканер. Введи код вручную.'))};document.head.append(script)})}
function stopCamera(){scannerNonce++;try{scannerControls?.stop()}catch{}scannerControls=null;if(scannerVideo?.srcObject){scannerVideo.srcObject.getTracks().forEach(t=>t.stop());scannerVideo.srcObject=null}scannerVideo=null}
async function startCamera(){if(!navigator.mediaDevices?.getUserMedia){remoteStatus('Этот браузер не даёт доступ к камере. Введи код вручную.',true);return}stopCamera();let nonce=scannerNonce,area=document.getElementById('scanner-area');if(!area)return;area.innerHTML='<div class="scanner-view"><video id="barcode-video" autoplay muted playsinline></video><div class="scan-frame"></div></div><p class="field-note">Наведи камеру на штрихкод. Лучше работают хорошее освещение и ровная упаковка.</p><button class="btn small outline" type="button" data-tracker="stop-camera">Выключить камеру</button>';remoteStatus('Запускаем камеру…');try{await loadScanner();if(nonce!==scannerNonce||!modal.open)return;scannerVideo=document.getElementById('barcode-video');const reader=new ZXingBrowser.BrowserMultiFormatOneDReader(undefined,{delayBetweenScanAttempts:350});let found=false;const controls=await reader.decodeFromConstraints({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false},scannerVideo,(result,error,ctrl)=>{if(!result||found||nonce!==scannerNonce)return;let code=result.getText();if(!/^(?:\d{8}|\d{12}|\d{13}|\d{14})$/.test(code))return;found=true;ctrl.stop();stopCamera();const input=document.getElementById('barcode-input');if(input)input.value=code;area.innerHTML='';lookupBarcode(code)});if(nonce!==scannerNonce){controls.stop();return}scannerControls=controls;remoteStatus('Камера работает. Ожидаем штрихкод.')}catch(e){if(nonce!==scannerNonce)return;stopCamera();area.innerHTML='';remoteStatus(e.name==='NotAllowedError'?'Доступ к камере не разрешён. Можно ввести код вручную.':e.name==='NotFoundError'?'Камера не найдена. Введи код вручную.':e.message||'Не удалось запустить камеру. Введи код вручную.',true)}}
modal.addEventListener('close',()=>{stopCamera();stopFoodRequest()});
const originalTrackerValidate=validateBackup;
validateBackup=function(x){const o=originalTrackerValidate(x);o.products={};for(let p of Object.values(x.products||{})){let cp=cleanProduct(p);o.products[cp.id]=cp}o.profile.glassSize=Number.isFinite(x.profile.glassSize)&&x.profile.glassSize>=50&&x.profile.glassSize<=1000?x.profile.glassSize:250;if(Array.isArray(x.habitDefs)){if(x.habitDefs.length>60)throw Error('Слишком много привычек в копии');o.habitDefs=x.habitDefs.map(h=>{if(!h||!String(h.name||'').trim()||!validDate(h.created))throw Error('Некорректная привычка в копии');return{id:String(h.id).slice(0,120),name:String(h.name).slice(0,80),desc:String(h.desc||'').slice(0,180),created:h.created,archived:validDate(h.archived)?h.archived:null}})}for(let [dt,d]of Object.entries(x.days)){if(!o.days[dt])continue;let out=o.days[dt];if(Array.isArray(d.entries)){if(d.entries.length>1000)throw Error('Слишком много записей за день');out.entries=d.entries.map(e=>{const kind=e.kind==='portion'?'portion':'product',max=kind==='portion'?[10000,1000,1000,1000]:[1000,100,100,100];if(!e||!Array.isArray(e.base)||e.base.length!==4||!e.base.every((n,i)=>Number.isFinite(n)&&n>=0&&n<=max[i])||!Number.isFinite(e.amount)||e.amount<=0||e.amount>(kind==='portion'?20:5000))throw Error('Некорректная запись питания в копии');return{id:String(e.id||uid('entry')).slice(0,120),kind,name:String(e.name||'Продукт').slice(0,140),brand:String(e.brand||'').slice(0,100),barcode:String(e.barcode||'').replace(/\D/g,'').slice(0,14),base:e.base.slice(),amount:e.amount,unit:kind==='portion'?'portion':e.unit==='ml'?'ml':'g',meal:TRACKER_MEALS.includes(e.meal)?e.meal:'Другое',source:['manual','builtin','openfoodfacts','legacy','recipe'].includes(e.source)?e.source:'manual',productId:String(e.productId||'').slice(0,120),at:typeof e.at==='string'?e.at.slice(0,40):''}})}if(Array.isArray(d.waterLogs)){if(d.waterLogs.length>1000)throw Error('Слишком много записей воды');out.waterLogs=d.waterLogs.map(w=>{if(!w||!Number.isFinite(w.amount)||w.amount<=0||w.amount>10000)throw Error('Некорректная запись воды');return{id:String(w.id||uid('water')).slice(0,120),amount:w.amount,at:String(w.at||'').slice(0,40),label:String(w.label||'Вода').slice(0,80)}});out.water=out.waterLogs.reduce((n,w)=>n+w.amount,0)}out.habits={};for(let [id,val]of Object.entries(d.habits||{}))if(id.length<120&&!['__proto__','constructor','prototype'].includes(id))out.habits[id]=!!val;if(d.trackerVersion===2)out.trackerVersion=2}if(x.stepConnection?.key&&/^[a-f0-9-]{36}$/i.test(x.stepConnection.key))o.stepConnection={key:x.stepConnection.key};if(x.trackerVersion===2)o.trackerVersion=2;return o};
function saveProductForm(form){const f=new FormData(form),base=['kcal','p','f','c'].map(k=>Number(f.get(k))),amount=Number(f.get('amount'));if(!Number.isFinite(amount)||amount<=0||amount>5000){toast('Проверь размер порции');return}let p;try{p=cleanProduct({...foodSelected,name:String(f.get('name')),brand:String(f.get('brand')),barcode:String(f.get('barcode')),base,unit:String(f.get('unit'))})}catch(e){toast(e.message);return}state.products[p.id]=p;const e={id:foodEditId||uid('entry'),kind:'product',name:p.name,brand:p.brand,barcode:p.barcode,base:p.base.slice(),amount,unit:p.unit,meal:String(f.get('meal')),source:p.source,productId:p.id,at:new Date().toISOString()};let d=trackerDay();if(foodEditId){const i=d.entries.findIndex(v=>v.id===foodEditId);if(i>=0)d.entries[i]=e;else d.entries.push(e)}else d.entries.push(e);save();modal.close();render();toast(foodEditId?'Запись обновлена':'Продукт добавлен в дневник')}
// Controls for the new tracker use their own namespace and do not alter workout actions.
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-tracker],[data-food-tab]');if(!el)return;if(el.dataset.foodTab){foodTab=el.dataset.foodTab;render();return}const action=el.dataset.tracker;switch(action){case'add-food':foodPicker(el.dataset.meal);break;case'food-mode':stopCamera();stopFoodRequest();foodSession++;foodMode=el.dataset.mode;showFoodPicker();break;case'back-to-food':foodEditId=null;showFoodPicker();break;case'manual-product':productReview();if(el.dataset.barcode){foodSelected.barcode=el.dataset.barcode;showProductForm()}break;case'library-filter':productLibraryMode=el.dataset.filter;modal.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===productLibraryMode));updateLocalResults();break;case'favorite-product':{let p=productById(el.dataset.product);if(!p)return;state.products[p.id]={...p,favorite:!p.favorite};save();updateLocalResults();break}case'select-product':{let p=el.dataset.remote==='1'?lookupResults.find(p=>p.id===el.dataset.product):productById(el.dataset.product);if(p)productReview(p);break}case'edit-entry':editDiaryEntry(el.dataset.id);break;case'delete-entry':{let d=trackerDay(),i=d.entries.findIndex(e=>e.id===el.dataset.id);if(i<0)return;lastFoodRemoved={date:selected,index:i,entry:d.entries[i]};d.entries.splice(i,1);save();render();toast('Запись удалена. Её можно вернуть в дневнике.');break}case'undo-food':if(lastFoodRemoved){trackerDay(lastFoodRemoved.date).entries.splice(lastFoodRemoved.index,0,lastFoodRemoved.entry);lastFoodRemoved=null;save();render()}break;case'log-recipe':logRecipe(Number(el.dataset.slot));break;case'glass':{let d=trackerDay(),id='glass-'+el.dataset.glass,w=d.waterLogs.find(w=>w.id===id);if(w){d.waterLogs=d.waterLogs.filter(w=>w.id!==id);setWaterTotal();save();render()}else addWater(state.profile.glassSize||250,id);break}case'add-glass':{let d=trackerDay(),i=0;while(d.waterLogs.some(w=>w.id==='glass-'+i))i++;addWater(state.profile.glassSize||250,i<24?'glass-'+i:null);break}case'water-custom':dialog('Добавить воду',`<form id="water-form"><label>Выпитый объём, мл<input name="amount" type="number" min="1" max="3000" step="1" inputmode="numeric" required value="${state.profile.glassSize||250}"></label><button class="btn" type="submit" style="width:100%;margin-top:18px">${ico('plus')}Записать воду</button></form>`);break;case'glass-size':dialog('Размер твоего стакана',`<form id="glass-size-form"><label>Объём, мл<input name="size" type="number" min="50" max="1000" step="1" inputmode="numeric" required value="${state.profile.glassSize||250}"></label><p class="field-note">Изменится объём новых отметок. Уже выпитая вода останется в истории с прежним объёмом.</p><button class="btn" type="submit">Сохранить</button></form>`);break;case'remove-water':{let d=trackerDay();d.waterLogs=d.waterLogs.filter(w=>w.id!==el.dataset.id);setWaterTotal();save();render();break}case'habit-toggle':{let d=trackerDay();d.habits[el.dataset.id]=!d.habits[el.dataset.id];save();render();break}case'new-habit':addHabitDialog();break;case'manage-habits':habitDialog();break;case'archive-habit':{let h=state.habitDefs.find(h=>h.id===el.dataset.id);if(h)h.archived=selected;save();habitDialog();render();break}case'start-camera':startCamera();break;case'stop-camera':stopCamera();document.getElementById('scanner-area').innerHTML='';remoteStatus('Камера выключена.');break}});
document.addEventListener('input',ev=>{const e=ev.target;if(e.id==='product-query'){productSearchQuery=e.value;updateLocalResults()}if(e.dataset.nutri!==undefined||e.id==='food-amount')updatePortionPreview()});
document.addEventListener('change',ev=>{if(ev.target.id==='food-unit')updatePortionPreview()});
document.addEventListener('submit',ev=>{const form=ev.target,f=new FormData(form);if(['product-form','barcode-form','food-search-form','habit-form','water-form','glass-size-form','recipe-entry-form','portion-entry-form'].includes(form.id))ev.preventDefault();switch(form.id){case'product-form':saveProductForm(form);break;case'barcode-form':stopCamera();lookupBarcode(f.get('barcode'));break;case'food-search-form':searchRemoteFoods(f.get('query'));break;case'habit-form':{const name=String(f.get('habitName')||'').trim();if(!name||state.habitDefs.length>=60){toast('Проверь название или количество привычек');return}state.habitDefs.push({id:uid('habit'),name:name.slice(0,80),desc:String(f.get('habitDesc')||'').slice(0,180),created:selected,archived:null});save();modal.close();render();toast('Привычка добавлена');break}case'water-form':{let n=Number(f.get('amount'));if(n<1||n>3000||!Number.isFinite(n))return;modal.close();addWater(n);break}case'glass-size-form':{let n=Number(f.get('size'));if(n<50||n>1000||!Number.isFinite(n))return;state.profile.glassSize=n;save();modal.close();render();break}case'recipe-entry-form':{let amount=Number(f.get('amount')),r=mealFor(Number(f.get('slot')));if(!Number.isFinite(amount)||amount<=0||amount>10)return;trackerDay().entries.push({id:uid('recipe'),kind:'portion',name:r.name,base:macros(r.foods),amount,unit:'portion',meal:r.type,source:'recipe',at:new Date().toISOString()});save();modal.close();foodTab='diary';render();toast('Съеденная порция записана');break}case'portion-entry-form':{let e=trackerDay().entries.find(e=>e.id===f.get('entryId')),n=Number(f.get('amount'));if(!e||n<=0||n>20||!Number.isFinite(n))return;e.amount=n;e.meal=String(f.get('meal'));save();modal.close();render();break}}});
CHAPTERS.unshift(['Новый дневник продуктов','Теперь меню служит примером. Калории дня складываются только из реальных записей дневника. Добавь продукт из базовых, сохранённых или Open Food Facts, проверь значения на 100 г или 100 мл и укажи съеденную порцию. Изменение библиотеки не переписывает прошлые записи. Старые отмеченные блюда переносятся в дневник автоматически.'],['Продукты, базы и штрихкоды','Базовые продукты доступны без внешнего запроса. Поиск в Open Food Facts и поиск штрихкода требуют интернета и могут находить не все российские продукты. Данные добавляют пользователи, поэтому сверяй этикетку. При отсутствии данных создай свой продукт и сохрани код для следующих покупок. FatSecret и YAZIO сейчас не подключены: без отдельного доступа их базы не используются.'],['Вода и привычки','Каждый стакан можно отметить и снять. Размер стакана настраивается, прежние записи сохраняют свой объём. Добавляй произвольные миллилитры и смотри историю дня. Свои привычки отмечай вручную, а вода, белок и шаги отмечаются автоматически по дневнику. Это ориентиры, а не повод пить или есть через силу.']);

// iPhone Shortcuts bridge: only daily Huawei step totals, carried in a URL fragment.
let stepBridgePending=null;
function stepBridgeKey(){return KEY+'-iphone-steps'}
function bridgeConfig(){try{const c=JSON.parse(localStorage.getItem(stepBridgeKey())||'null')||state.stepConnection||null;if(c?.key){if(!state.stepConnection){state.stepConnection=c;save()}if(!localStorage.getItem(stepBridgeKey()))localStorage.setItem(stepBridgeKey(),JSON.stringify(c));return c}return null}catch{return state.stepConnection||null}}
function parseStepTransfer(hash){if(!hash.startsWith('#health-steps?'))return null;const q=new URLSearchParams(hash.slice(14)),date=q.get('date'),raw=q.get('steps');if(!date||!/^\d{4}-\d{2}-\d{2}$/.test(date)||localDate(dateObj(date))!==date||date>TODAY||date<shift(TODAY,-7)||!raw||!/^\d{1,6}$/.test(raw)||Number(raw)>100000)throw Error('Нужны дата за последние 7 дней и целое число шагов от 0 до 100 000.');return{date,steps:Number(raw),key:q.get('key')}}
function bridgeCard(){const c=bridgeConfig();return `<section class="card" style="margin:20px 0"><div class="eyebrow">HUAWEI → APPLE ЗДОРОВЬЕ → ФОРМА</div><h3>Шаги с iPhone</h3><p class="long-note" style="margin:12px 0">${c?'Приём шагов включён в этом браузере. Запускай команду «ФОРМА Шаги»: она прочитает данные и откроет дневник.':'Подключи команду iPhone, чтобы переносить шаги Huawei из Apple «Здоровья».'} Обычное открытие Safari не даёт сайту доступ к «Здоровью».</p><div class="flex wrap"><button class="btn small soft" data-steps="setup">${c?'Инструкция настройки':'Настроить передачу'}</button>${c?'<a class="btn small" href="shortcuts://run-shortcut?name='+encodeURIComponent('ФОРМА Шаги')+'">Обновить через «Команды»</a><button class="text-link" data-steps="disconnect">Отключить приём</button>':''}</div>${trackerDay().stepSync?'<p class="field-note">Последний импорт: '+esc(new Date(trackerDay().stepSync.at).toLocaleString('ru-RU'))+' · Huawei через команду iPhone. Ручная правка шагов имеет приоритет до следующего импорта.</p>':''}</section>`}
function bridgeSetup(){let c=bridgeConfig();if(!c){dialog('Передача шагов с iPhone',`<p class="long-note">Команда будет читать только шаги Huawei за день и передавать число и дату в этот браузер. Они сохранятся в локальном дневнике. Данные передаются после знака # в адресе и не отправляются серверу GitHub, но адрес может остаться в истории браузера. Доступ к «Здоровью» ты разрешишь на iPhone.</p><button class="btn" data-steps="enable" style="margin-top:18px">Включить приём и показать инструкцию</button>`);return}const template=location.origin+location.pathname+'#health-steps?date=[ДАТА]&steps=[ШАГИ]&key='+c.key;dialog('Команда «ФОРМА Шаги»',`<p class="long-note">Однократно создай в приложении iPhone «Команды» команду с точным названием <b>ФОРМА Шаги</b>. Названия действий могут отличаться в твоей версии iOS.</p><ol class="bridge-instructions"><li>Добавь «Найти образцы здоровья» (Find Health Samples): тип <b>Шаги</b>, дата начала <b>сегодня</b>, источник <b>HUAWEI Health</b>. Отключи ограничение количества. Не выбирай одновременно iPhone и часы: их сырые записи могут дублироваться.</li><li>Получи числовые значения найденных образцов и сложи их действием «Вычислить статистику» → <b>Сумма</b>. Если образцов нет, покажи уведомление и останови команду — не передавай ноль вместо отсутствующих данных.</li><li>Добавь «Текущая дата» → «Форматировать дату»: свой формат <b>yyyy-MM-dd</b>.</li><li>Добавь действие «Текст» с шаблоном ниже. Вместо <b>[ДАТА]</b> вставь переменную отформатированной даты, вместо <b>[ШАГИ]</b> — сумму шагов целым числом без пробелов. Квадратные скобки удали.</li><li>Добавь «Открыть URL» с этим текстом. Разреши команде читать шаги. Открывай ссылку в том же Safari, где ведёшь дневник, без приватного режима.</li></ol><label>Шаблон адреса<textarea readonly rows="5" id="step-template">${esc(template)}</textarea></label><p class="field-note">Передача заменяет итог дня, а не прибавляет шаги. Сначала синхронизируй часы с Huawei Health. При первом запуске сравни итог с источником Huawei в Apple «Здоровье». Если итог отличается, не подтверждай импорт.</p><p class="long-note">Для привычного запуска добавь команду на экран «Домой» и открывай трекер через неё: сначала обновятся шаги, затем откроется сайт. Автозапуск при каждом открытии Safari здесь не включается.</p><a class="text-link" href="https://support.apple.com/guide/shortcuts/run-a-shortcut-from-a-url-apd624386f42/ios" target="_blank" rel="noopener">Справка Apple о запуске команд</a>`)}
function acceptStepTransfer(){const p=stepBridgePending;if(!p)return;if(p.reconnect){state.stepConnection={key:p.key};try{localStorage.setItem(stepBridgeKey(),JSON.stringify(state.stepConnection))}catch{}}const d=trackerDay(p.date);d.steps=p.steps;d.stepSync={source:'huawei-shortcuts',at:new Date().toISOString()};selected=p.date;view='home';stepBridgePending=null;save();modal.close();render();toast('Шаги за '+fmtDate(p.date)+' обновлены')}
function receiveStepTransfer(){if(!location.hash.startsWith('#health-steps?'))return;let p;try{p=parseStepTransfer(location.hash)}catch(e){history.replaceState(null,'',location.pathname+location.search+'#home');toast(e.message);return}history.replaceState(null,'',location.pathname+location.search+'#home');const c=bridgeConfig();if(!/^[a-f0-9-]{36}$/i.test(p.key||'')){toast('Адрес команды неполный: отсутствует ключ подключения.');return}p.reconnect=!c||p.key!==c.key;stepBridgePending=p;dialog('Подтвердить шаги',`${p.reconnect?'<p class="info-strip">Связь с этой командой не найдена. Подтверждение восстановит её в этом браузере — менять команду на iPhone не нужно.</p>':''}<p class="long-note">${esc(fmtDate(p.date,true))}: <b>${num(p.steps)} шагов</b>.<br>Сейчас в дневнике: ${trackerDay(p.date).steps===''?'нет записи':num(trackerDay(p.date).steps)}. Новый итог заменит старый. Сверь его с Huawei в Apple «Здоровье».</p><button class="btn" data-steps="accept" style="width:100%;margin-top:18px">Записать ${num(p.steps)} шагов</button><button class="text-link" data-action="close-modal" style="margin-top:15px">Отмена</button>`)}
const renderWithoutStepBridge=render;
render=function(scroll=false){renderWithoutStepBridge(scroll);if(view==='settings')root.insertAdjacentHTML('beforeend',bridgeCard());if(DATA)receiveStepTransfer();updateStorageWarning()};
window.addEventListener('hashchange',()=>{if(DATA)receiveStepTransfer()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-steps]');if(!b)return;switch(b.dataset.steps){case'setup':bridgeSetup();break;case'enable':try{state.stepConnection=bridgeConfig()||{key:crypto.randomUUID()};localStorage.setItem(stepBridgeKey(),JSON.stringify(state.stepConnection));save();bridgeSetup();render()}catch{toast('Не удалось сохранить подключение. Проверь доступ к хранилищу.')}break;case'disconnect':localStorage.removeItem(stepBridgeKey());delete state.stepConnection;save();render();toast('Приём отключён. История шагов сохранена.');break;case'accept':acceptStepTransfer();break}});

// Save edited profile fields without requiring the distant form submit button.
document.addEventListener('change',ev=>{const e=ev.target;if(e.closest?.('#profile-form')&&e.name&&e.checkValidity()){const numeric=['age','height','baseline','kcal','protein','fat','steps','water','dayA','dayB'];if(numeric.includes(e.name)){if(e.value==='')return;state.profile[e.name]=Number(e.value)}else if(e.name==='club1Name'||e.name==='club2Name'){state.profile.clubNames||={};state.profile.clubNames[e.name==='club1Name'?'club1':'club2']=e.value.slice(0,80)}else if(['start','notes','foodsNote'].includes(e.name))state.profile[e.name]=e.value;else return;save()} });
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const latest=JSON.parse(e.newValue);if(latest.version!==1)return;state=mergeStoredChanges(persistedState,state,latest);persistedState=structuredClone(latest);if(DATA&&!modal.open&&!document.activeElement?.closest?.('input,textarea,select'))render()}catch{}});
window.addEventListener('pageshow',()=>{try{const latest=readStoredState();if(!latest)return;state=mergeStoredChanges(persistedState,state,latest);persistedState=structuredClone(latest);if(DATA&&!modal.open)render()}catch{}});

function recoveryDatabase(){return new Promise((resolve,reject)=>{if(typeof indexedDB==='undefined'){reject(Error('IndexedDB unavailable'));return}const request=indexedDB.open('forma-durable-history',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('history'))request.result.createObjectStore('history')};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('Database blocked'))})}
async function loadRecoveryDatabase(){try{const db=await recoveryDatabase();return await new Promise(resolve=>{const tx=db.transaction('history','readonly'),req=tx.objectStore('history').get('latest');req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>resolve(null);tx.oncomplete=()=>db.close()})}catch{return null}}
async function writeRecoveryDatabase(snapshot){try{const copy=structuredClone(snapshot),db=await recoveryDatabase();const tx=db.transaction('history','readwrite');tx.objectStore('history').put(copy,'latest');tx.oncomplete=()=>db.close();tx.onerror=()=>db.close()}catch{}}

function updateStorageWarning(){if(typeof document==='undefined'||!document.body)return;let box=document.getElementById('storage-warning');if(storageOK){box?.remove();return}if(!box){box=document.createElement('div');box.id='storage-warning';box.className='storage-warning';box.setAttribute('role','alert');document.body.append(box)}box.innerHTML='Не удаётся сохранить данные на устройстве. Не закрывай страницу. <button data-action="export">Скачать резервную копию</button> <button data-storage="check">Проверить причину</button>'}
function storageReport(){let writable=false,error='';try{const key=KEY+'-probe',value=String(Date.now());localStorage.setItem(key,value);writable=localStorage.getItem(key)===value;localStorage.removeItem(key)}catch(e){error=e.name}const raw=readStoredState(),days=Object.values(raw?.days||{});return{build:12,writable,error,stored:!!raw,savedAt:raw?.savedAt||null,days:days.length,entries:days.reduce((n,d)=>n+(d.entries?.length||0),0),waterDays:days.filter(d=>d.water>0).length,measurements:raw?.measurements?.length||0,pairing:!!bridgeConfig(),mode:matchMedia('(display-mode: standalone)').matches?'Иконка приложения':'Браузер',origin:location.origin}}
async function showStorageReport(){const r=storageReport();storageOK=r.writable;updateStorageWarning();const durable=await loadRecoveryDatabase();dialog('Сохранение и восстановление',`<p class="long-note">${r.writable?'Запись в хранилище сейчас проходит.':'Браузер блокирует запись'+(r.error?' ('+esc(r.error)+')':'')+'. Скачай копию перед закрытием страницы.'}</p><div class="storage-report"><p>Версия: <b>${r.build}</b> · ${esc(r.mode)}</p><p>Последнее сохранение: <b>${r.savedAt?esc(new Date(r.savedAt).toLocaleString('ru-RU')):'пока нет отметки'}</b></p><p>Дней в истории: <b>${r.days}</b> · продуктов: <b>${r.entries}</b> · дней с водой: <b>${r.waterDays}</b> · замеров: <b>${r.measurements}</b></p><p>Связь с командой шагов: <b>${r.pairing?'сохранена':'нет'}</b></p><p>Дополнительная копия: <b>${durable?'есть':'пока нет / недоступна'}</b></p></div><p class="field-note">Эта проверка не отправляет данные. Вода и шаги считаются отдельно для каждой даты; вчерашние записи доступны через календарь. Профиль и подключение должны сохраняться между днями.</p><button class="btn" data-action="export" style="width:100%;margin-top:15px">Скачать полную резервную копию</button><button class="btn soft" data-storage="reload-check" style="width:100%;margin-top:10px">Сохранить и проверить перезагрузкой</button><p class="field-note">Если сброс повторится, пришли скриншот этой проверки: здесь нет веса, названий еды и медицинских заметок.</p>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-storage]');if(!b)return;if(b.dataset.storage==='check')showStorageReport();if(b.dataset.storage==='reload-check'){if(save())location.reload()}});
// Save valid measurement edits immediately, without replacing the form during typing.
document.addEventListener('change',ev=>{const form=ev.target.closest?.('#measure-form');if(!form)return;const f=new FormData(form),weight=Number(f.get('weight'));if(!Number.isFinite(weight)||weight<35||weight>250||!form.checkValidity())return;const measurement={date:selected,weight,waist:f.get('waist')?Number(f.get('waist')):null,sleep:f.get('sleep')?Number(f.get('sleep')):null,note:String(f.get('note')||'').trim()};state.measurements=state.measurements.filter(m=>m.date!==selected);state.measurements.push(measurement);save()});

function walkingEstimate(steps,s=selected){const latest=state.measurements.filter(m=>m.date<=s&&Number(m.weight)>=35&&Number(m.weight)<=250).sort((a,b)=>b.date.localeCompare(a.date))[0],weight=latest?Number(latest.weight):Number(state.profile.baseline),height=Number(state.profile.height);if(!Number.isFinite(weight)||weight<35||weight>250)return null;if(steps===''||steps===null||!Number.isFinite(Number(steps))||Number(steps)<0||Number(steps)>100000)return null;const stepMeters=height>=120&&height<=230?height/100*.415:.70,km=Number(steps)*stepMeters/1000,minutes=km/4*60;return{weight,stepMeters,km,minutes,active:(3-1)*3.5*weight/200*minutes,gross:3*3.5*weight/200*minutes,measured:!!latest,heightKnown:height>=120&&height<=230}}
function walkingCaloriesPanel(steps=trackerDay().steps){const e=walkingEstimate(steps);if(!e)return `<div class="walking-estimate"><span class="eyebrow">ОБЫЧНАЯ ХОДЬБА</span><p class="long-note">${steps===''?'Запиши шаги, чтобы увидеть примерный расход калорий.':'Для оценки калорий укажи массу в профиле или сохрани замер веса.'}</p><button class="text-link" data-nav="settings">Мой профиль</button></div>`;return `<section class="walking-estimate"><div class="eyebrow">ОБЫЧНАЯ ХОДЬБА · ОЦЕНКА</div><div class="walking-kcal">≈ ${num(Math.round(e.active/5)*5)} <span>активных ккал</span></div><p class="field-note">${num(Number(steps))} шагов · около ${num(e.km,1)} км · вес ${num(e.weight,1)} кг</p><details><summary>Как рассчитано</summary><p class="field-note">Предполагаем ровную поверхность, обычный темп около 4 км/ч и 3 MET. Длина шага ${num(e.stepMeters,2)} м ${e.heightKnown?'оценена по росту':'принята условно, рост не указан'}. Получается около ${num(Math.round(e.minutes))} минут движения. Активные калории — расход сверх покоя; вместе с расходом покоя за это время ≈ ${num(Math.round(e.gross/5)*5)} ккал.</p><p class="field-note">Это расчётная модель, а не измерение часами: темп, остановки, длина шага и уклон меняют результат. Если среди шагов был бег, эта оценка для него не подходит. Калории еды не увеличиваем: обычная активность уже может быть учтена в твоём дневном ориентире.</p><a class="text-link" href="https://pacompendium.com/walking/" target="_blank" rel="noopener">Основа: Compendium 2024, ходьба 17170</a></details></section>`}
document.addEventListener('input',ev=>{if(ev.target.id==='daily-steps'){const panel=document.getElementById('walking-calories');if(panel)panel.innerHTML=walkingCaloriesPanel(ev.target.value)}});

// Health overview and recipe library. Legacy food entries remain in backups only.
const HEALTH_FIELDS={steps:{name:'Шаги',unit:'',max:100000},kcal:{name:'Калории питания',unit:'ккал',max:15000},protein:{name:'Белки',unit:'г',max:1500},fat:{name:'Жиры',unit:'г',max:1500},carbs:{name:'Углеводы',unit:'г',max:2000},active:{name:'Активная энергия',unit:'ккал',max:15000},water:{name:'Вода из Здоровья',unit:'мл',max:15000}};
function parseHealthOverview(hash){if(!hash.startsWith('#health?'))return null;const q=new URLSearchParams(hash.slice(8)),date=q.get('date'),key=q.get('key');if(!validDate(date)||date>TODAY||date<shift(TODAY,-7)||!/^[a-f0-9-]{36}$/i.test(key||''))throw Error('Проверь дату и ключ в команде.');const values={};for(const [field,meta]of Object.entries(HEALTH_FIELDS)){const count=q.get(field+'Count'),raw=q.get(field);if(count!==null&&(!/^\d+$/.test(count)||Number(count)>100000))throw Error('Некорректное количество записей: '+meta.name);if(count==='0'||raw===null||raw.trim()==='')continue;const text=raw.replace(/[\s\u00a0\u202f]/g,'').replace(',','.');if(!/^\d+(?:\.\d+)?$/.test(text))throw Error('Неверное значение: '+meta.name);const n=Number(text);if(!Number.isFinite(n)||n<0||n>meta.max||(field==='steps'&&!Number.isInteger(n)))throw Error('Проверь значение: '+meta.name);values[field]=n}if(!Object.keys(values).length)throw Error('В команде нет доступных данных за этот день. Разреши чтение в «Здоровье».');return{date,key,values}}
let pendingHealthOverview=null;
function receiveHealthOverview(){if(!location.hash.startsWith('#health?'))return;let p;try{p=parseHealthOverview(location.hash)}catch(e){history.replaceState(null,'',location.pathname+location.search+'#home');toast(e.message);return}history.replaceState(null,'',location.pathname+location.search+'#home');pendingHealthOverview=p;const reconnect=bridgeConfig()?.key!==p.key;dialog('Данные Apple «Здоровья»',`${reconnect?'<p class="info-strip">При подтверждении восстановим подключение этой команды.</p>':''}<p class="long-note">${esc(fmtDate(p.date,true))}. Выбери показатели для обновления. Импорт заменяет итог дня и не прибавляется к старому дневнику еды.</p><form id="health-overview-form"><div class="health-import-list">${Object.entries(p.values).map(([k,v])=>`<label><input type="checkbox" name="healthField" value="${k}" checked><span>${HEALTH_FIELDS[k].name}</span><b>${num(v,k==='steps'?0:1)} ${HEALTH_FIELDS[k].unit}</b></label>`).join('')}</div><p class="field-note">Сверь питание с FatSecret. Если источники в «Здоровье» дублируются, сними соответствующие отметки. Нет записей — прежний показатель сохраняется. Вода из «Здоровья» и стаканы на сайте показываются раздельно.</p><button class="btn" type="submit" style="width:100%">Сохранить выбранные показатели</button></form>`)}
document.addEventListener('submit',ev=>{if(ev.target.id!=='health-overview-form')return;ev.preventDefault();const p=pendingHealthOverview;if(!p)return;const selectedFields=new FormData(ev.target).getAll('healthField');if(!selectedFields.length){toast('Выбери хотя бы один показатель');return}const d=trackerDay(p.date);d.health||={};const at=new Date().toISOString();for(const k of selectedFields){if(!(k in p.values))continue;d.health[k]={value:p.values[k],at,source:'apple-health'};if(k==='steps'){d.steps=p.values[k];d.stepSync={at,source:'apple-health'}}}state.stepConnection={key:p.key};try{localStorage.setItem(stepBridgeKey(),JSON.stringify(state.stepConnection))}catch{}state.profile.healthShortcutName='ФОРМА Здоровье';if(!save())return;selected=p.date;view='home';pendingHealthOverview=null;modal.close();render();toast('Данные «Здоровья» обновлены')});
const stepTransferReceiver=receiveStepTransfer;
receiveStepTransfer=function(){if(location.hash.startsWith('#health?'))receiveHealthOverview();else stepTransferReceiver()};
window.addEventListener('hashchange',()=>{if(DATA)receiveHealthOverview()});
function healthValue(field,s=selected){return trackerDay(s).health?.[field]?.value??null}
eaten=function(s=selected){return['kcal','protein','fat','carbs'].map(k=>healthValue(k,s)??0)};
macroCards=function(){return `<div class="macro-grid">${[['kcal','Питание',state.profile.kcal,'ккал'],['protein','Белок',state.profile.protein,'г'],['fat','Жиры',state.profile.fat,'г'],['carbs','Углеводы',targetCarbs(),'г']].map(([k,title,target,unit])=>{const v=healthValue(k);return `<section class="card macro-card"><div class="stat-top">${title} · Здоровье</div><div class="stat-num">${v===null?'—':num(v,0)} <small>${unit}</small></div><div class="track"><i style="width:${v===null?0:clamp(v/target*100,0,100)}%"></i></div><p class="field-note">${v===null?'Пока нет импорта':'Ориентир '+num(target)+' '+unit}</p></section>`}).join('')}</div>`};
function healthNutritionCard(){const fields=['kcal','protein','fat','carbs'],records=fields.map(k=>trackerDay().health?.[k]).filter(Boolean),last=records.map(r=>r.at).sort().pop();return `<section class="card"><div class="eyebrow">ПИТАНИЕ ИЗ APPLE ЗДОРОВЬЯ</div><h3>FatSecret остаётся твоим дневником</h3><p class="long-note" style="margin:12px 0">Калории и БЖУ показываем из импортированных итогов «Здоровья». Продукты вручную здесь вводить больше не нужно. ${last?'Последний импорт: '+esc(new Date(last).toLocaleString('ru-RU'))+'.':'Запусти новую команду «ФОРМА Здоровье», чтобы передать питание.'}</p><a class="btn small" href="shortcuts://run-shortcut?name=${encodeURIComponent('ФОРМА Здоровье')}">Обновить данные здоровья</a><p class="field-note">Старые записи еды сохранены в резервной копии, но не прибавляются к БЖУ из «Здоровья».</p><button class="text-link" data-nav="meals">Найти вкусный рецепт ${ico('right')}</button></section>`}
compactDiary=healthNutritionCard;
const homeWithLegacyCopy=home;
home=function(){let html=homeWithLegacyCopy();html=html.replace(/<button class="btn lime small" data-tracker="add-food">.*?<\/button>/,'<button class="btn lime small" data-nav="meals">'+ico('food')+'Найти рецепт</button>').replace('Что уже съедено','Питание из «Здоровья»').replace(/<span class="tag">\d+ записей<\/span>/,'<span class="tag">Итоги дня</span>').replace('Рацион можно собрать из любимой еды, а пример меню оставить для вдохновения.','Питайся вкусно, отслеживай движение и выбирай рецепты под свой день.');return html};
NAV.find(n=>n[0]==='meals')[1]='Рецепты';
let recipeQuery='',recipeCategory='Все',recipeQuick=false,recipeProtein=false,recipeOnlyFavorites=false,recipeLimit=24;
function recipeResults(){let words=recipeQuery.toLocaleLowerCase('ru').trim().split(/\s+/).filter(Boolean);return DATA.recipes.filter(r=>words.every(w=>(r.name+' '+r.foods.map(f=>f[0]).join(' ')).toLocaleLowerCase('ru').includes(w))&&(recipeCategory==='Все'||r.type===recipeCategory)&&(!recipeQuick||(r.minutes||20)<=15)&&(!recipeProtein||macros(r.foods)[1]>=25)&&(!recipeOnlyFavorites||state.recipeFavorites?.[r.id]))}
function recipeLibraryCard(r){const v=macros(r.foods),fav=!!state.recipeFavorites?.[r.id];return `<article class="card recipe-library-card"><div class="flex between"><span class="tag">${esc(r.type)} · ${r.minutes||20} мин</span><button class="favorite-btn ${fav?'is-favorite':''}" data-recipe="favorite" data-id="${esc(r.id)}" aria-label="${fav?'Убрать из избранного':'В избранное'}: ${esc(r.name)}">${fav?'★':'☆'}</button></div><h3>${esc(r.name)}</h3><div class="recipe-kcal">≈ ${round(v[0])} <span>ккал / порция</span></div><p class="field-note">Б ${round(v[1])} · Ж ${round(v[2])} · У ${round(v[3])} г</p><p class="recipe-preview">${r.foods.slice(0,4).map(f=>esc(f[0].replace(/,.*$/,''))).join(' · ')}</p><button class="btn soft small" data-recipe="open" data-id="${esc(r.id)}">Ингредиенты и приготовление</button></article>`}
function recipeResultsMarkup(){const rs=recipeResults();return `<p class="field-note">Найдено: ${rs.length}. Калории и БЖУ приблизительные, на одну указанную порцию.</p><div class="grid two recipe-library-grid">${rs.slice(0,recipeLimit).map(recipeLibraryCard).join('')}</div>${!rs.length?'<div class="empty">Попробуй другой запрос или отключи фильтры.</div>':''}${rs.length>recipeLimit?'<button class="btn outline" style="width:100%;margin:20px 0" data-recipe="more">Показать ещё 24 рецепта</button>':''}`}
meals=function(){return head('Рецепты для твоего ритма','Большая подборка без мяты. Выбирай по вкусу, времени и белку.',false)+`<section class="card recipe-toolbar"><div class="flex wrap between"><span class="tag">${DATA.recipes.length} рецептов</span><button class="text-link" data-recipe="favorites">${recipeOnlyFavorites?'Показать все':'★ Только избранное'}</button></div><label style="margin-top:14px">Поиск по блюду или ингредиенту<input id="recipe-query" value="${esc(recipeQuery)}" placeholder="Например, курица, суп или творог" autocomplete="off"></label><div class="recipe-categories">${['Все','Завтрак','Обед','Ужин','Перекус'].map(c=>`<button class="${c===recipeCategory?'active':''}" data-recipe="category" data-category="${c}">${c}</button>`).join('')}</div><div class="flex wrap"><button class="btn small ${recipeQuick?'':'soft'}" data-recipe="quick">До 15 минут ${recipeQuick?'✓':''}</button><button class="btn small ${recipeProtein?'':'soft'}" data-recipe="protein">От 25 г белка ${recipeProtein?'✓':''}</button></div><p class="field-note">Это идеи для готовки. Выбранный рецепт не записывается как съеденный и не меняет данные FatSecret. Для заготовок время охлаждения и предварительной готовки указано в описании.</p></section><div id="recipe-results">${recipeResultsMarkup()}</div>`};
function openLibraryRecipe(id,portions=1){const r=DATA.recipes.find(r=>r.id===id);if(!r)return;const v=macros(r.foods);dialog(r.name,`<span class="tag">${esc(r.type)} · ${r.minutes||20} минут</span><p class="field-note">На 1 порцию: ≈ ${round(v[0])} ккал · Б ${round(v[1])} / Ж ${round(v[2])} / У ${round(v[3])} г</p><label style="margin-top:15px">Сколько порций готовим?<select id="recipe-servings" data-recipe-id="${esc(id)}">${[1,2,3,4].map(n=>`<option value="${n}" ${n===portions?'selected':''}>${n}</option>`).join('')}</select></label><div class="recipe-ingredient-list">${r.foods.map(([f,g])=>`<div class="ingredient"><span>${esc(f)}</span><b>${num(g*portions,1)} г</b></div>`).join('')}</div><h3 style="margin:20px 0 10px">Как приготовить</h3><p class="long-note">${esc(r.method)}</p><p class="field-note">Мясо и рыба указаны сырыми, крупы сухими, если в названии ингредиента не сказано «готовый», «отварной» или «варёный». Дополнительные соусы и масло меняют БЖУ. Без мяты; остальные ограничения проверяй по составу.</p><button class="btn soft" data-recipe="favorite" data-id="${esc(id)}" style="width:100%;margin-top:15px">${state.recipeFavorites?.[id]?'★ В избранном':'☆ Сохранить в избранное'}</button>`)}
document.addEventListener('input',ev=>{if(ev.target.id!=='recipe-query')return;recipeQuery=ev.target.value;recipeLimit=24;document.getElementById('recipe-results').innerHTML=recipeResultsMarkup()});
document.addEventListener('change',ev=>{if(ev.target.id==='recipe-servings')openLibraryRecipe(ev.target.dataset.recipeId,Number(ev.target.value))});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-recipe]');if(!b)return;const a=b.dataset.recipe;if(a==='open'){openLibraryRecipe(b.dataset.id);return}if(a==='favorite'){state.recipeFavorites||={};state.recipeFavorites[b.dataset.id]=!state.recipeFavorites[b.dataset.id];save();if(modal.open){openLibraryRecipe(b.dataset.id,Number(document.getElementById('recipe-servings')?.value||1));return}}if(a==='category')recipeCategory=b.dataset.category;if(a==='quick')recipeQuick=!recipeQuick;if(a==='protein')recipeProtein=!recipeProtein;if(a==='favorites')recipeOnlyFavorites=!recipeOnlyFavorites;if(a==='more'){recipeLimit+=24;document.getElementById('recipe-results').innerHTML=recipeResultsMarkup();return}recipeLimit=24;render()});
const validateBeforeHealth=validateBackup;
validateBackup=function(x){const o=validateBeforeHealth(x);if(x.profile?.healthShortcutName==='ФОРМА Здоровье')o.profile.healthShortcutName='ФОРМА Здоровье';o.recipeFavorites={};for(const [id,fav]of Object.entries(x.recipeFavorites||{}))if(/^[a-zA-Z0-9_-]{1,120}$/.test(id)&&!['__proto__','constructor','prototype'].includes(id))o.recipeFavorites[id]=!!fav;for(const [dt,d]of Object.entries(x.days||{})){if(!o.days[dt])continue;o.days[dt].health={};for(const [k,v]of Object.entries(d.health||{})){if(!(k in HEALTH_FIELDS)||!Number.isFinite(v?.value)||v.value<0||v.value>HEALTH_FIELDS[k].max)continue;o.days[dt].health[k]={value:v.value,at:String(v.at||'').slice(0,40),source:'apple-health'}}}return o};
const walkingModelPanel=walkingCaloriesPanel;
walkingCaloriesPanel=function(steps=trackerDay().steps){const active=healthValue('active');return(active===null?'':`<div class="walking-estimate"><div class="eyebrow">АКТИВНАЯ ЭНЕРГИЯ · APPLE ЗДОРОВЬЕ</div><div class="walking-kcal">${num(active)} <span>ккал</span></div><p class="field-note">Импортированный расход всей активности. Это не только ходьба. Не прибавляется к лимиту питания.</p></div>`)+walkingModelPanel(steps)};
const manualWaterPanel=waterPanel;
waterPanel=function(full=false){let html=manualWaterPanel(full),v=healthValue('water');if(v!==null)html=html.replace(/<\/section>$/,`<div class="info-strip" style="margin-top:15px">В Apple «Здоровье»: <b>${num(v)} мл</b>. Это отдельный итог; к отмеченным здесь стаканам не прибавляем, чтобы не задвоить воду.</div></section>`);return html};

CHAPTERS.splice(0,2,['Питание из Apple «Здоровья»','Веди еду в FatSecret, разреши передачу калорий и БЖУ в Apple «Здоровье», затем запускай команду «ФОРМА Здоровье». Перед сохранением сверь числа. Сайт заменяет выбранные итоги дня, не прибавляет старые продукты. Пустые данные не считаются нулём.'],['Рецепты вместо второго дневника','В разделе «Рецепты» — 130 вариантов с поиском, фильтрами и избранным. Граммовки можно пересчитать на 1–4 порции. Выбор рецепта не означает, что ты его съел: запись питания остаётся в FatSecret. БЖУ рецептов приблизительные, состав проверяй по упаковкам.']);
